import subprocess, time
def tmux(*a): return subprocess.run(["tmux"]+list(a), capture_output=True, text=True)
def cap(name="t1", esc=False):
    args=["capture-pane","-t",name,"-p"]+(["-e"] if esc else [])
    return tmux(*args).stdout
def S(cmd, keys=[], w=80, h=24, name="t1", wait=0.6, esc=False, only_last=False, full=False):
    tmux("kill-session","-t",name)
    tmux("new-session","-d","-s",name,"-x",str(w),"-y",str(h), cmd)
    time.sleep(wait)
    def show(label):
        c=cap(name,esc)
        if full: print(f"---{label}---\n{c}")
        elif only_last:
            lines=c.rstrip("\n").split("\n")
            print(f"{label}: status={lines[-1]!r} top={lines[0]!r}")
        else: print(f"---{label}---\n{c}")
    print("CMD",cmd); show("0")
    for idx,k in enumerate(keys):
        if isinstance(k,(int,float)): time.sleep(k)
        elif isinstance(k,list):
            # if list of strings send sequentially as one step? tmux send-keys multiple keys as separate args works but literal string issue.
            tmux("send-keys","-t",name,*k); time.sleep(0.35)
        else: tmux("send-keys","-t",name,k); time.sleep(0.35)
        if tmux("has-session","-t",name).returncode!=0:
            print(f"{idx+1} after {k!r} EXITED"); break
        show(f"{idx+1} after {k!r}")
    tmux("kill-session","-t",name)

def send_text(text):
    # returns a tmux send-keys list using -l
    return ["-l", text]
