	}
	// For default (set==nil) styles, a non-zero field counts as set.
	get := func(cond bool, field string) bool {
		if over.set != nil {
			return over.set[field]
		}
		return cond
	}
	if get(over.Foreground != "", "foreground") {
		r.Foreground = over.Foreground
	}
	if get(over.Background != "", "background") {
		r.Background = over.Background
	}
	if get(over.UnderlineColor != "", "underlinecolor") {
		r.UnderlineColor = over.UnderlineColor
	}
	if get(over.Bold, "bold") {
		r.Bold = over.Bold
	}
	if get(over.Blink, "blink") {
		r.Blink = over.Blink
	}
	if get(over.Dim, "dim") {
		r.Dim = over.Dim
	}
	if get(over.Italic, "italic") {
		r.Italic = over.Italic
	}
	if get(over.Reverse, "reverse") {
		r.Reverse = over.Reverse
	}
	if get(over.Underline, "underline") {
		r.Underline = over.Underline
	}
	if get(over.Strikethrough, "strikethrough") {
		r.Strikethrough = over.Strikethrough
	}
	if get(over.UnderlineStyle != 0, "underlinestyle") {
