}

func defaultConfig() *Config {
	return &Config{
		Incsearch:       true,
		MemoryLimit:     -1,
		MemoryLimitFile: 100,
		ShrinkChar:      "…",
		ReadWaitTime:    time.Second,
		KeyBind:         map[string][]string{},
		General:         defaultGeneral(),
		ModeRaws:        map[string]map[string]any{},
	}
}

var supportedExts = []string{"json", "toml", "yaml", "yml", "properties", "props", "prop", "hcl", "tfvars", "dotenv", "env", "ini"}

func isSupportedExt(ext string) bool {
	for _, e := range supportedExts {
		if e == ext {
			return true
		}
	}
	return false
}

type configNotFoundError string

func (e configNotFoundError) Error() string { return string(e) }

var (
	cfg             = defaultConfig()
	cfgUsedFile     string
	cfgExplicitFile string
)

// parseConfigData parses raw config bytes by ext into a map.
func parseConfigData(data []byte, ext string) (map[string]any, error) {
	switch ext {
	case "yaml", "yml":
		if len(strings.TrimSpace(string(data))) == 0 {
			return map[string]any{}, nil
		}
		var m map[string]any
		if err := yaml.Unmarshal(data, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %w", err)
		}
		if m == nil {
			m = map[string]any{}
		}
		return m, nil
	case "json":
		var m map[string]any
		if err := json.Unmarshal(data, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %w", err)
		}
		if m == nil {
			m = map[string]any{}
		}
		return m, nil
	case "toml":
		var m map[string]any
		if err := toml.Unmarshal(data, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %w", err)
		}
		if m == nil {
			m = map[string]any{}
		}
		return m, nil
	case "dotenv", "env":
		m := map[string]any{}
		for _, line := range strings.Split(string(data), "\n") {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			if i := strings.Index(line, "="); i >= 0 {
				m[strings.TrimSpace(line[:i])] = strings.Trim(strings.TrimSpace(line[i+1:]), "\"'")
			}
		}
		return m, nil
	default:
		// properties/props/prop/hcl/tfvars/ini are supported types without a decoder.
		return nil, fmt.Errorf("While parsing config: decoder not found for this format")
	}
}

func configSearchDir() string {
	if x := os.Getenv("XDG_CONFIG_HOME"); x != "" {
		return filepath.Join(x, "ov")
	}
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		home = os.Getenv("HOME")
	}
	return filepath.Join(home, ".config", "ov")
}

// loadConfig replicates viper-ish ReadInConfig + Unmarshal error reporting.
func loadConfig(explicit string, debugFlag bool) {
	cfg = defaultConfig()
	cfgUsedFile = ""
	cfgExplicitFile = explicit

	var file string
	var ext string
	var readErr error
	var data []byte
	var isNotFound bool

	if explicit != "" {
		file = explicit
		cfgUsedFile = explicit
		ext = strings.TrimPrefix(filepath.Ext(explicit), ".")
		if !isSupportedExt(ext) {
			readErr = fmt.Errorf("Unsupported Config Type %q", ext)
		} else {
			d, err := os.ReadFile(explicit)
			if err != nil {
				// os error string matches Go ("open <file>: ...")
				readErr = err
			} else {
				data = d
			}
		}
	} else {
		dir := configSearchDir()
		found := ""
		for _, e := range supportedExts {
			p := filepath.Join(dir, "config."+e)
			if fi, err := os.Stat(p); err == nil && !fi.IsDir() {
				found = p
				ext = e
				break
			}
		}
		if found == "" {
			readErr = configNotFoundError(fmt.Sprintf("Config File \"config\" Not Found in \"[%s]\"", dir))
			isNotFound = true
		} else {
			file = found
			cfgUsedFile = found
			d, err := os.ReadFile(found)
			if err != nil {
				readErr = err
			} else {
				data = d
			}
		}
	}

	_ = file
	var rootMap map[string]any
	if readErr == nil && data != nil {
		m, err := parseConfigData(data, ext)
		if err != nil {
			readErr = err
		} else {
			rootMap = m
		}
	}

	if readErr != nil {
		if !(isNotFound && !debugFlag) {
			fmt.Fprintf(os.Stderr, "failed to read config file: %s\n", readErr.Error())
		}
	}
	if rootMap == nil {
		return
	}

	errs := decodeConfig(rootMap)
	if len(errs) > 0 {
		fmt.Fprintf(os.Stderr, "decoding failed due to the following error(s):\n\n")
		for _, e := range errs {
			fmt.Fprintf(os.Stderr, "%s\n", e)
		}
	}
}

func decodeConfig(root map[string]any) []string {
	var errs []string
	// General first (to report General errors in deterministic place is hard; map iteration random is OK)
	if gv, ok := lookup(root, "General"); ok {
		if gm, ok := asMap(gv); ok {
			cfg.General.applyMap(gm, "General", &errs)
		} else if gv != nil {
			errs = append(errs, fmt.Sprintf("'General' expected type 'oviewer.General', got unconvertible type '%s'", typeName(gv)))
		}
	}
	for k, v := range root {
		lk := strings.ToLower(k)
		intF := func(dst *int, fname string) {
			n, err := asInt(v)
			if err != nil {
				errs = append(errs, fmt.Sprintf("'%s' cannot parse value as 'int': strconv.ParseInt: invalid syntax", fname))
				return
			}
			*dst = int(n)
		}
		boolF := func(dst *bool, fname string) {
			b, err := asBool(v)
			if err != nil {
				errs = append(errs, fmt.Sprintf("'%s' cannot parse value as 'bool': strconv.ParseBool: invalid syntax", fname))
				return
			}
			*dst = b
		}
		strF := func(dst *string) {
			s, _ := asString(v)
			*dst = s
		}
		switch lk {
		case "general":
			// handled above
		case "quitsmall":
			boolF(&cfg.QuitSmall, "Quitsmall")
		case "iswriteoriginal":
			boolF(&cfg.IsWriteOriginal, "IsWriteOriginal")
		case "beforewriteoriginal":
			intF(&cfg.BeforeWriteOriginal, "BeforeWriteOriginal")
		case "afterwriteoriginal":
			intF(&cfg.AfterWriteOriginal, "AfterWriteOriginal")
		case "casesensitive":
			boolF(&cfg.CaseSensitive, "CaseSensitive")
		case "smartcasesensitive":
			boolF(&cfg.SmartCaseSensitive, "SmartCaseSensitive")
		case "regexpsearch":
			boolF(&cfg.RegexpSearch, "RegexpSearch")
		case "incsearch":
			boolF(&cfg.Incsearch, "Incsearch")
		case "memorylimit":
			intF(&cfg.MemoryLimit, "MemoryLimit")
		case "memorylimitfile":
			intF(&cfg.MemoryLimitFile, "MemoryLimitFile")
		case "disablemouse":
			boolF(&cfg.DisableMouse, "DisableMouse")
		case "disablecolumncycle":
			boolF(&cfg.DisableColumnCycle, "DisableColumnCycle")
		case "disablestickyfollow":
			boolF(&cfg.DisableStickyFollow, "DisableStickyFollow")
		case "viewmode":
			strF(&cfg.ViewMode)
		case "clipboardmethod":
			strF(&cfg.ClipboardMethod)
		case "setterminaltitle":
			boolF(&cfg.SetTerminalTitle, "SetTerminalTitle")
		case "debug":
			boolF(&cfg.Debug, "Debug")
		case "shrinkchar":
			strF(&cfg.ShrinkChar)
		case "readwaittime":
			if s, err := asString(v); err == nil {
				if d, err := time.ParseDuration(s); err == nil {
					cfg.ReadWaitTime = d
				}
			}
		case "defaultkeybind":
			strF(&cfg.DefaultKeyBind)
		case "styleoverstrike":
			if sm, ok := asMap(v); ok {
				cfg.StyleOverStrike = styleFromMap(sm)
			}
		case "styleoverline":
			if sm, ok := asMap(v); ok {
				cfg.StyleOverLine = styleFromMap(sm)
			}
		case "keybind":
			if km, ok := asMap(v); ok {
				for action, val := range km {
					var keys []string
					if lst, ok := asList(val); ok {
						for _, e := range lst {
							s, _ := asString(e)
							keys = append(keys, s)
						}
					} else {
						// weakly typed: scalar becomes a single element slice
						s, _ := asString(val)
						keys = []string{s}
					}
					cfg.KeyBind[strings.ToLower(action)] = keys
					// keep original case key too for exact lookups? actions are lowercase.
					_ = action
				}
			}
		case "mode":
			if mm, ok := asMap(v); ok {
				for name, mv := range mm {
					if gm, ok := asMap(mv); ok {
						cfg.ModeRaws[strings.ToLower(name)] = gm
					}
				}
			} else if v != nil {
				errs = append(errs, fmt.Sprintf("'Mode' expected type 'map[string]oviewer.General', got unconvertible type '%s'", typeName(v)))
			}
		}
	}
	return errs
}

