package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/BurntSushi/toml"
	"gopkg.in/yaml.v3"
)

// ---- value coercion helpers (weakly typed, like viper/mapstructure) ----

func asString(v any) (string, error) {
	switch t := v.(type) {
	case string:
		return t, nil
	case []byte:
		return string(t), nil
	case bool:
		return strconv.FormatBool(t), nil
	case int:
		return strconv.Itoa(t), nil
	case int64:
		return strconv.FormatInt(t, 10), nil
	case float64:
		if t == float64(int64(t)) {
			return strconv.FormatInt(int64(t), 10), nil
		}
		return strconv.FormatFloat(t, 'g', -1, 64), nil
	case nil:
		return "", nil
	default:
		return fmt.Sprintf("%v", v), nil
	}
}

func asBool(v any) (bool, error) {
	switch t := v.(type) {
	case bool:
		return t, nil
	case string:
		return strconv.ParseBool(t)
	case int:
		return t != 0, nil
	case int64:
		return t != 0, nil
	case float64:
		return t != 0, nil
	default:
		return false, fmt.Errorf("cannot parse '%v' as bool", v)
	}
}

func asInt(v any) (int64, error) {
	switch t := v.(type) {
	case int:
		return int64(t), nil
	case int64:
		return t, nil
	case uint64:
		return int64(t), nil
	case float64:
		return int64(t), nil
	case float32:
		return int64(t), nil
	case string:
		n, err := strconv.ParseInt(t, 0, 64)
		if err != nil {
			return 0, err
		}
		return n, nil
	case bool:
		if t {
			return 1, nil
		}
		return 0, nil
	default:
		return 0, fmt.Errorf("cannot parse as int")
	}
}

func asMap(v any) (map[string]any, bool) {
	switch t := v.(type) {
	case map[string]any:
		return t, true
	case map[any]any:
		m := map[string]any{}
		for k, val := range t {
			m[fmt.Sprintf("%v", k)] = val
		}
		return m, true
	default:
		return nil, false
	}
}

func asList(v any) ([]any, bool) {
	switch t := v.(type) {
	case []any:
		return t, true
	case []string:
		out := make([]any, len(t))
		for i, e := range t {
			out[i] = e
		}
		return out, true
	default:
		return nil, false
	}
}

// lowerKeys converts map with lowercased keys for lookup convenience.
func lookup(m map[string]any, key string) (any, bool) {
	lk := strings.ToLower(key)
	for k, v := range m {
		if strings.ToLower(k) == lk {
			return v, true
		}
	}
	return nil, false
}

func typeName(v any) string {
	if v == nil {
		return "<nil>"
	}
	switch v.(type) {
	case int:
		return "int"
	case float64:
		return "float64"
	case string:
		return "string"
	case bool:
		return "bool"
	case []any:
		return "[]interface {}"
	case map[string]any:
		return "map[string]interface {}"
	default:
		return fmt.Sprintf("%T", v)
	}
}

// ---- General (view) settings ----
type General struct {
	TabWidth               int
	Header                 int
	SkipLines              int
	AlternateRows          bool
	ColumnMode             bool
	LineNumMode            bool
	WrapMode               bool
	ColumnDelimiter        string
	ColumnRainbow          bool
	ColumnWidth            bool
	Align                  bool
	Plain                  bool
	Raw                    bool
	Converter              string
	MarkStyleWidth         int
	HScrollWidth           string
	VScrollLines           int
	SectionDelimiter       string
	SectionHeader          bool
	SectionHeaderNum       int
	SectionStart           int
	HideOtherSection       bool
	VerticalHeader         int
	HeaderColumn           int
	Ruler                  int
	JumpTarget             string
	Style                  Styles
	PromptShowFilename     bool
	PromptInvertColor      bool
	PromptProcessOfCount   bool
	PromptNormalCursorType int
	PromptInputCursorType  int
}

func defaultGeneral() General {
	return General{
		TabWidth:               8,
		WrapMode:               true,
		ColumnDelimiter:        ",",
		Converter:              "es",
		MarkStyleWidth:         1,
		HScrollWidth:           "10%",
		VScrollLines:           2,
		SectionHeaderNum:       1,
		Style:                  defaultStyles(),
		PromptShowFilename:     true,
		PromptInvertColor:      true,
		PromptNormalCursorType: 0,
		PromptInputCursorType:  1,
	}
}

// applyMap applies all fields present in m; collects decode errors like mapstructure.
func (g *General) applyMap(m map[string]any, path string, errs *[]string) {
	for k, v := range m {
		lk := strings.ToLower(k)
		intField := func(dst *int, fname string) {
			n, err := asInt(v)
			if err != nil {
				*errs = append(*errs, fmt.Sprintf("'%s.%s' cannot parse value as 'int': strconv.ParseInt: invalid syntax", path, fname))
				return
			}
			*dst = int(n)
		}
		boolField := func(dst *bool, fname string) {
			b, err := asBool(v)
			if err != nil {
				*errs = append(*errs, fmt.Sprintf("'%s.%s' cannot parse value as 'bool': strconv.ParseBool: invalid syntax", path, fname))
				return
			}
			*dst = b
		}
		strField := func(dst *string) {
			s, _ := asString(v)
			*dst = s
		}
		switch lk {
		case "tabwidth":
			intField(&g.TabWidth, "TabWidth")
		case "header":
			intField(&g.Header, "Header")
		case "skiplines":
			intField(&g.SkipLines, "SkipLines")
		case "alternaterows":
			boolField(&g.AlternateRows, "AlternateRows")
		case "columnmode":
			boolField(&g.ColumnMode, "ColumnMode")
		case "linenumeremode", "linenumemode":
			boolField(&g.LineNumMode, "LineNumMode")
		case "linenummode":
			boolField(&g.LineNumMode, "LineNumMode")
		case "wrapmode":
			boolField(&g.WrapMode, "WrapMode")
		case "columndelimiter":
			strField(&g.ColumnDelimiter)
		case "columnrainbow":
			boolField(&g.ColumnRainbow, "ColumnRainbow")
		case "columnwidth":
			boolField(&g.ColumnWidth, "ColumnWidth")
		case "align":
			boolField(&g.Align, "Align")
		case "plain":
			boolField(&g.Plain, "Plain")
		case "raw":
			boolField(&g.Raw, "Raw")
		case "converter":
			strField(&g.Converter)
		case "markstylewidth":
			intField(&g.MarkStyleWidth, "MarkStyleWidth")
		case "hscrollwidth":
			s, _ := asString(v)
			if n, ok := v.(int); ok {
				s = strconv.Itoa(n)
			}
			g.HScrollWidth = s
		case "vscrolllines":
			intField(&g.VScrollLines, "VScrollLines")
		case "sectiondelimiter":
			strField(&g.SectionDelimiter)
		case "sectionheader":
			boolField(&g.SectionHeader, "SectionHeader")
		case "sectionheadernum":
			intField(&g.SectionHeaderNum, "SectionHeaderNum")
		case "sectionstart":
			intField(&g.SectionStart, "SectionStart")
		case "hideothersection":
			boolField(&g.HideOtherSection, "HideOtherSection")
		case "verticalheader":
			intField(&g.VerticalHeader, "VerticalHeader")
		case "headercolumn":
			intField(&g.HeaderColumn, "HeaderColumn")
		case "ruler":
			intField(&g.Ruler, "Ruler")
		case "jumptarget":
			strField(&g.JumpTarget)
		case "style":
			if sm, ok := asMap(v); ok {
				applyStylesMap(&g.Style, sm)
			}
		case "prompt":
			if pm, ok := asMap(v); ok {
				if nv, ok := lookup(pm, "Normal"); ok {
					if nm, ok := asMap(nv); ok {
						if x, ok := lookup(nm, "ShowFilename"); ok {
							b, _ := asBool(x)
							g.PromptShowFilename = b
						}
						if x, ok := lookup(nm, "InvertColor"); ok {
							b, _ := asBool(x)
							g.PromptInvertColor = b
						}
						if x, ok := lookup(nm, "ProcessOfCount"); ok {
							b, _ := asBool(x)
							g.PromptProcessOfCount = b
						}
						if x, ok := lookup(nm, "CursorType"); ok {
							n, _ := asInt(x)
							g.PromptNormalCursorType = int(n)
						}
					}
				}
				if iv, ok := lookup(pm, "Input"); ok {
					if im, ok := asMap(iv); ok {
						if x, ok := lookup(im, "CursorType"); ok {
							n, _ := asInt(x)
							g.PromptInputCursorType = int(n)
						}
					}
				}
			}
		}
	}
}

// ---- Top-level config ----
type Config struct {
	QuitSmall           bool
	IsWriteOriginal     bool
	BeforeWriteOriginal int
	AfterWriteOriginal  int
	CaseSensitive       bool
	SmartCaseSensitive  bool
	RegexpSearch        bool
	Incsearch           bool
	MemoryLimit         int
	MemoryLimitFile     int
	DisableMouse        bool
	DisableColumnCycle  bool
	DisableStickyFollow bool
	ViewMode            string
	ClipboardMethod     string
	SetTerminalTitle    bool
	Debug               bool
	ShrinkChar          string
	ReadWaitTime        time.Duration
	StyleOverStrike     StyleCfg
	StyleOverLine       StyleCfg
	DefaultKeyBind      string
	KeyBind             map[string][]string
	General             General
	ModeRaws            map[string]map[string]any // mode name (lowercase) -> general map
}

func defaultConfig() *Config {
	return &Config{
		Incsearch:       true,
		MemoryLimit:     -1,
		MemoryLimitFile: 100,
		ShrinkChar:      "…",
		ReadWaitTime:    time.Second,
		KeyBind:         map[string][]string{},
		General:         defaultGeneral(),
		ModeRaws:        map[string]map[string]any{},
	}
}

var supportedExts = []string{"json", "toml", "yaml", "yml", "properties", "props", "prop", "hcl", "tfvars", "dotenv", "env", "ini"}

func isSupportedExt(ext string) bool {
	for _, e := range supportedExts {
		if e == ext {
			return true
		}
	}
	return false
}

type configNotFoundError string

func (e configNotFoundError) Error() string { return string(e) }

var (
	cfg             = defaultConfig()
	cfgUsedFile     string
	cfgExplicitFile string
)

// parseConfigData parses raw config bytes by ext into a map.
func parseConfigData(data []byte, ext string) (map[string]any, error) {
	switch ext {
	case "yaml", "yml":
		if len(strings.TrimSpace(string(data))) == 0 {
			return map[string]any{}, nil
		}
		var m map[string]any
		if err := yaml.Unmarshal(data, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %w", err)
		}
		if m == nil {
			m = map[string]any{}
		}
		return m, nil
	case "json":
		var m map[string]any
		if err := json.Unmarshal(data, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %w", err)
		}
		if m == nil {
			m = map[string]any{}
		}
		return m, nil
	case "toml":
		var m map[string]any
		if err := toml.Unmarshal(data, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %w", err)
		}
		if m == nil {
			m = map[string]any{}
		}
		return m, nil
	case "dotenv", "env":
		m := map[string]any{}
		for _, line := range strings.Split(string(data), "\n") {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			if i := strings.Index(line, "="); i >= 0 {
				m[strings.TrimSpace(line[:i])] = strings.Trim(strings.TrimSpace(line[i+1:]), "\"'")
			}
		}
		return m, nil
	default:
		// properties/props/prop/hcl/tfvars/ini are supported types without a decoder.
		return nil, fmt.Errorf("While parsing config: decoder not found for this format")
	}
}

func configSearchDir() string {
	if x := os.Getenv("XDG_CONFIG_HOME"); x != "" {
		return filepath.Join(x, "ov")
	}
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		home = os.Getenv("HOME")
	}
	return filepath.Join(home, ".config", "ov")
}

// loadConfig replicates viper-ish ReadInConfig + Unmarshal error reporting.
func loadConfig(explicit string, debugFlag bool) {
	cfg = defaultConfig()
	cfgUsedFile = ""
	cfgExplicitFile = explicit

	var file string
	var ext string
	var readErr error
	var data []byte
	var isNotFound bool

	if explicit != "" {
		file = explicit
		cfgUsedFile = explicit
		ext = strings.TrimPrefix(filepath.Ext(explicit), ".")
		if !isSupportedExt(ext) {
			readErr = fmt.Errorf("Unsupported Config Type %q", ext)
		} else {
			d, err := os.ReadFile(explicit)
			if err != nil {
				// os error string matches Go ("open <file>: ...")
				readErr = err
			} else {
				data = d
			}
		}
	} else {
		dir := configSearchDir()
		found := ""
		for _, e := range supportedExts {
			p := filepath.Join(dir, "config."+e)
			if fi, err := os.Stat(p); err == nil && !fi.IsDir() {
				found = p
				ext = e
				break
			}
		}
		if found == "" {
			readErr = configNotFoundError(fmt.Sprintf("Config File \"config\" Not Found in \"[%s]\"", dir))
			isNotFound = true
		} else {
			file = found
			cfgUsedFile = found
			d, err := os.ReadFile(found)
			if err != nil {
				readErr = err
			} else {
				data = d
			}
		}
	}

	_ = file
	var rootMap map[string]any
	if readErr == nil && data != nil {
		m, err := parseConfigData(data, ext)
		if err != nil {
			readErr = err
		} else {
			rootMap = m
		}
	}

	if readErr != nil {
		if !(isNotFound && !debugFlag) {
			fmt.Fprintf(os.Stderr, "failed to read config file: %s\n", readErr.Error())
		}
	}
	if rootMap == nil {
		return
	}

	errs := decodeConfig(rootMap)
	if len(errs) > 0 {
		fmt.Fprintf(os.Stderr, "decoding failed due to the following error(s):\n\n")
		for _, e := range errs {
			fmt.Fprintf(os.Stderr, "%s\n", e)
		}
	}
}

func decodeConfig(root map[string]any) []string {
	var errs []string
	// General first (to report General errors in deterministic place is hard; map iteration random is OK)
	if gv, ok := lookup(root, "General"); ok {
		if gm, ok := asMap(gv); ok {
			cfg.General.applyMap(gm, "General", &errs)
		} else if gv != nil {
			errs = append(errs, fmt.Sprintf("'General' expected type 'oviewer.General', got unconvertible type '%s'", typeName(gv)))
		}
	}
	for k, v := range root {
		lk := strings.ToLower(k)
		intF := func(dst *int, fname string) {
			n, err := asInt(v)
			if err != nil {
				errs = append(errs, fmt.Sprintf("'%s' cannot parse value as 'int': strconv.ParseInt: invalid syntax", fname))
				return
			}
			*dst = int(n)
		}
		boolF := func(dst *bool, fname string) {
			b, err := asBool(v)
			if err != nil {
				errs = append(errs, fmt.Sprintf("'%s' cannot parse value as 'bool': strconv.ParseBool: invalid syntax", fname))
				return
			}
			*dst = b
		}
		strF := func(dst *string) {
			s, _ := asString(v)
			*dst = s
		}
		switch lk {
		case "general":
			// handled above
		case "quitsmall":
			boolF(&cfg.QuitSmall, "Quitsmall")
		case "iswriteoriginal":
			boolF(&cfg.IsWriteOriginal, "IsWriteOriginal")
		case "beforewriteoriginal":
			intF(&cfg.BeforeWriteOriginal, "BeforeWriteOriginal")
		case "afterwriteoriginal":
			intF(&cfg.AfterWriteOriginal, "AfterWriteOriginal")
		case "casesensitive":
			boolF(&cfg.CaseSensitive, "CaseSensitive")
		case "smartcasesensitive":
			boolF(&cfg.SmartCaseSensitive, "SmartCaseSensitive")
		case "regexpsearch":
			boolF(&cfg.RegexpSearch, "RegexpSearch")
		case "incsearch":
			boolF(&cfg.Incsearch, "Incsearch")
		case "memorylimit":
			intF(&cfg.MemoryLimit, "MemoryLimit")
		case "memorylimitfile":
			intF(&cfg.MemoryLimitFile, "MemoryLimitFile")
		case "disablemouse":
			boolF(&cfg.DisableMouse, "DisableMouse")
		case "disablecolumncycle":
			boolF(&cfg.DisableColumnCycle, "DisableColumnCycle")
		case "disablestickyfollow":
			boolF(&cfg.DisableStickyFollow, "DisableStickyFollow")
		case "viewmode":
			strF(&cfg.ViewMode)
		case "clipboardmethod":
			strF(&cfg.ClipboardMethod)
		case "setterminaltitle":
			boolF(&cfg.SetTerminalTitle, "SetTerminalTitle")
		case "debug":
			boolF(&cfg.Debug, "Debug")
		case "shrinkchar":
			strF(&cfg.ShrinkChar)
		case "readwaittime":
			if s, err := asString(v); err == nil {
				if d, err := time.ParseDuration(s); err == nil {
					cfg.ReadWaitTime = d
				}
			}
		case "defaultkeybind":
			strF(&cfg.DefaultKeyBind)
		case "styleoverstrike":
			if sm, ok := asMap(v); ok {
				cfg.StyleOverStrike = styleFromMap(sm)
			}
		case "styleoverline":
			if sm, ok := asMap(v); ok {
				cfg.StyleOverLine = styleFromMap(sm)
			}
		case "keybind":
			if km, ok := asMap(v); ok {
				for action, val := range km {
					var keys []string
					if lst, ok := asList(val); ok {
						for _, e := range lst {
							s, _ := asString(e)
							keys = append(keys, s)
						}
					} else {
						// weakly typed: scalar becomes a single element slice
						s, _ := asString(val)
						keys = []string{s}
					}
					cfg.KeyBind[strings.ToLower(action)] = keys
					// keep original case key too for exact lookups? actions are lowercase.
					_ = action
				}
			}
		case "mode":
			if mm, ok := asMap(v); ok {
				for name, mv := range mm {
					if gm, ok := asMap(mv); ok {
						cfg.ModeRaws[strings.ToLower(name)] = gm
					}
				}
			} else if v != nil {
				errs = append(errs, fmt.Sprintf("'Mode' expected type 'map[string]oviewer.General', got unconvertible type '%s'", typeName(v)))
			}
		}
	}
	return errs
}

func listViewModes() []string {
	modes := []string{"general"}
	for name := range cfg.ModeRaws {
		modes = append(modes, name)
	}
	sort.Strings(modes)
	return modes
}
EOF
