// applyMap applies all fields present in m; collects decode errors like mapstructure.
func (g *General) applyMap(m map[string]any, path string, errs *[]string) {
	for k, v := range m {
		lk := strings.ToLower(k)
		intField := func(dst *int, fname string) {
			n, err := asInt(v)
			if err != nil {
				*errs = append(*errs, fmt.Sprintf("'%s.%s' cannot parse value as 'int': strconv.ParseInt: invalid syntax", path, fname))
				return
			}
			*dst = int(n)
		}
		boolField := func(dst *bool, fname string) {
			b, err := asBool(v)
			if err != nil {
				*errs = append(*errs, fmt.Sprintf("'%s.%s' cannot parse value as 'bool': strconv.ParseBool: invalid syntax", path, fname))
				return
			}
			*dst = b
		}
		strField := func(dst *string) {
			s, _ := asString(v)
			*dst = s
		}
		switch lk {
		case "tabwidth":
			intField(&g.TabWidth, "TabWidth")
		case "header":
			intField(&g.Header, "Header")
		case "skiplines":
			intField(&g.SkipLines, "SkipLines")
		case "alternaterows":
			boolField(&g.AlternateRows, "AlternateRows")
		case "columnmode":
			boolField(&g.ColumnMode, "ColumnMode")
		case "linenumeremode", "linenumemode":
			boolField(&g.LineNumMode, "LineNumMode")
		case "linenummode":
			boolField(&g.LineNumMode, "LineNumMode")
		case "wrapmode":
			boolField(&g.WrapMode, "WrapMode")
		case "columndelimiter":
			strField(&g.ColumnDelimiter)
		case "columnrainbow":
			boolField(&g.ColumnRainbow, "ColumnRainbow")
		case "columnwidth":
			boolField(&g.ColumnWidth, "ColumnWidth")
		case "align":
			boolField(&g.Align, "Align")
		case "plain":
			boolField(&g.Plain, "Plain")
		case "raw":
			boolField(&g.Raw, "Raw")
		case "converter":
			strField(&g.Converter)
		case "markstylewidth":
			intField(&g.MarkStyleWidth, "MarkStyleWidth")
		case "hscrollwidth":
			s, _ := asString(v)
			if n, ok := v.(int); ok {
				s = strconv.Itoa(n)
			}
			g.HScrollWidth = s
		case "vscrolllines":
			intField(&g.VScrollLines, "VScrollLines")
		case "sectiondelimiter":
			strField(&g.SectionDelimiter)
		case "sectionheader":
			boolField(&g.SectionHeader, "SectionHeader")
		case "sectionheadernum":
			intField(&g.SectionHeaderNum, "SectionHeaderNum")
		case "sectionstart":
			intField(&g.SectionStart, "SectionStart")
		case "hideothersection":
			boolField(&g.HideOtherSection, "HideOtherSection")
		case "verticalheader":
			intField(&g.VerticalHeader, "VerticalHeader")
		case "headercolumn":
			intField(&g.HeaderColumn, "HeaderColumn")
		case "ruler":
			intField(&g.Ruler, "Ruler")
		case "jumptarget":
			strField(&g.JumpTarget)
		case "style":
			if sm, ok := asMap(v); ok {
				applyStylesMap(&g.Style, sm)
			}
		case "prompt":
			if pm, ok := asMap(v); ok {
				if nv, ok := lookup(pm, "Normal"); ok {
					if nm, ok := asMap(nv); ok {
						if x, ok := lookup(nm, "ShowFilename"); ok {
							b, _ := asBool(x)
							g.PromptShowFilename = b
						}
						if x, ok := lookup(nm, "InvertColor"); ok {
							b, _ := asBool(x)
							g.PromptInvertColor = b
						}
						if x, ok := lookup(nm, "ProcessOfCount"); ok {
							b, _ := asBool(x)
							g.PromptProcessOfCount = b
						}
						if x, ok := lookup(nm, "CursorType"); ok {
							n, _ := asInt(x)
							g.PromptNormalCursorType = int(n)
						}
					}
				}
				if iv, ok := lookup(pm, "Input"); ok {
					if im, ok := asMap(iv); ok {
						if x, ok := lookup(im, "CursorType"); ok {
							n, _ := asInt(x)
							g.PromptInputCursorType = int(n)
						}
					}
				}
			}
		}
	}
}

// ---- Top-level config ----
type Config struct {
	QuitSmall           bool
	IsWriteOriginal     bool
	BeforeWriteOriginal int
	AfterWriteOriginal  int
	CaseSensitive       bool
