// ---- formatting for --help-key ----

func formatKeyList(keys []string) string {
	if len(keys) == 0 {
		return "[]"
	}
	parts := make([]string, len(keys))
	for i, k := range keys {
		parts[i] = "[" + k + "]"
	}
	return strings.Join(parts, ", ")
}

func helpKeyString() string {
	kb := effectiveKeyBinds()
	var b strings.Builder
	b.WriteString("ov is a feature rich pager\n")
	fmt.Fprintf(&b, " %-30s Action\n\n", "Key")
	for _, sec := range helpSections {
