		for _, e := range sec.entries {
			fmt.Fprintf(&b, " %-30s * %s\n", formatKeyList(kb[e.action]), e.desc)
		}
		b.WriteString("\n")
	}
	// Invalid keybindings (from config-provided bindings).
	var invalid []string
	for action, keys := range cfg.KeyBind {
		for _, k := range keys {
			if !isValidKeyFormat(k) {
				invalid = append(invalid, fmt.Sprintf("Error: invalid key format: key %s for action %s", k, action))
			}
		}
	}
	if len(invalid) > 0 {
		b.WriteString("\n\tInvalid key bindings:\n")
		for _, s := range invalid {
			b.WriteString(s + "\n")
		}
