// ---- key-format validation (approximation of the reference behaviour) ----

var namedKeys map[string]bool

func init() {
	namedKeys = map[string]bool{}
	for _, name := range tcell.KeyNames {
		namedKeys[strings.ToLower(name)] = true
	}
	for _, extra := range []string{"escape", "space", "pageup", "pagedown", "pgup", "pgdn", "left", "right", "up", "down", "delete", "scrolllock", "capslock", "numlock", "print", "cancel", "exit", "menu", "pause"} {
		namedKeys[extra] = true
	}
}

func isModifierToken(tok string) bool {
	switch strings.ToLower(tok) {
	case "ctrl", "alt", "meta", "shift":
		return true
	}
	return false
}

func isValidKeyToken(tok string) bool {
	if tok == "" {
		return false
	}
	if isModifierToken(tok) {
		return true
	}
	if len([]rune(tok)) == 1 {
		return true
	}
	// F1..F64
	lt := strings.ToLower(tok)
	if len(lt) >= 2 && lt[0] == 'f' {
		if n, err := strconv.Atoi(lt[1:]); err == nil {
			return n >= 1 && n <= 64
		}
	}
	return namedKeys[lt]
}

func isValidKeyFormat(key string) bool {
	if key == "" {
		return false
	}
	if len([]rune(key)) == 1 {
		return true
	}
	// A trailing "++" denotes the '+' key with a modifier (e.g. ctrl++).
	s := key
	if strings.HasSuffix(s, "++") {
		rest := s[:len(s)-2]
		if rest == "" {
			return false // "++" alone
		}
		// validate the part before as modifiers/keys ending with a modifier
		parts := strings.Split(rest, "+")
		for _, p := range parts {
			if !isValidKeyToken(p) {
				return false
			}
		}
		return isModifierToken(parts[len(parts)-1])
	}
	parts := strings.Split(s, "+")
	for _, p := range parts {
		if !isValidKeyToken(p) {
			return false
		}
	}
	// last token must not be a bare modifier
	if isModifierToken(parts[len(parts)-1]) {
		return false
	}
	return true
}

// ---- descriptor used to match config keys against key events ----

type keyDesc struct {
	mods tcell.ModMask
	rune rune   // if isRune
	name string // otherwise lowercased base name
	isRune bool
}

func normalizeKeyName(name string) string {
	n := strings.ToLower(name)
	switch n {
	case "escape", "esc":
		return "esc"
	case "pageup", "pgup":
		return "pgup"
	case "pagedown", "pgdn":
		return "pgdn"
	case "space":
		return " "
	}
	return n
}

func parseKeyDesc(s string) (keyDesc, bool) {
	if s == "" {
		return keyDesc{}, false
	}
	base := s
	var mods tcell.ModMask
	// trailing ++ => base '+'
	parts := []string{}
	if strings.HasSuffix(s, "++") && len(s) > 2 {
		parts = append(strings.Split(s[:len(s)-2], "+"), "+")
	} else if s == "+" {
		parts = []string{"+"}
	} else {
		parts = strings.Split(s, "+")
	}
	for _, p := range parts[:len(parts)-1] {
		switch strings.ToLower(p) {
		case "ctrl":
			mods |= tcell.ModCtrl
		case "alt":
			mods |= tcell.ModAlt
		case "meta":
			mods |= tcell.ModMeta
		case "shift":
			mods |= tcell.ModShift
		default:
			// unknown middle token; ignore
		}
	}
	base = parts[len(parts)-1]
	nb := normalizeKeyName(base)
	if nb == " " {
		return keyDesc{mods: mods, rune: ' ', isRune: true}, true
	}
	if len([]rune(base)) == 1 {
		return keyDesc{mods: mods, rune: []rune(base)[0], isRune: true}, true
	}
	return keyDesc{mods: mods, name: nb}, true
}

func descFromEvent(ev *tcell.EventKey) keyDesc {
	mods := ev.Modifiers()
	if ev.Key() == tcell.KeyRune {
		return keyDesc{mods: mods, rune: ev.Rune(), isRune: true}
	}
	// Ctrl+letter style events: name like "Ctrl+C", rune set to lowercase letter.
	name := ev.Name()
	parts := strings.Split(name, "+")
	last := parts[len(parts)-1]
	if ev.Rune() != 0 {
		// control-letter: treat as rune with mods from event.
		return keyDesc{mods: mods, rune: ev.Rune(), isRune: true}
	}
	nb := normalizeKeyName(last)
	if nb == " " {
		return keyDesc{mods: mods, rune: ' ', isRune: true}
	}
	if len([]rune(last)) == 1 {
		return keyDesc{mods: mods, rune: []rune(last)[0], isRune: true}
	}
	return keyDesc{mods: mods, name: nb}
}

// keyActionMap builds desc -> action map for normal mode and input mode.
func buildActionMaps(kb map[string][]string) map[keyDesc]string {
	m := map[keyDesc]string{}
	for action, keys := range kb {
		for _, k := range keys {
			if d, ok := parseKeyDesc(k); ok {
				m[d] = action
			}
		}
	}
	return m
}
