	ViewMode          string
	Watch             int
	Wrap              bool
}

var opts Options

var version = "dev"
var revision = "HEAD"

func flagUsagesCustom(fs *pflag.FlagSet) string {
	type entry struct{ left, right string }
	var entries []entry
	max := 0
	fs.SortFlags = true
	fs.VisitAll(func(f *pflag.Flag) {
		if f.Hidden {
			return
		}
		var left string
		if f.Shorthand != "" && f.ShorthandDeprecated == "" {
			left = fmt.Sprintf("  -%s, --%s", f.Shorthand, f.Name)
		} else {
			left = fmt.Sprintf("      --%s", f.Name)
		}
		varname, usage := pflag.UnquoteUsage(f)
		if varname != "" {
			left += " " + varname
		}
		switch f.Name {
		case "incsearch", "status-line", "wrap":
			left += "[=true|false]"
		}
		if len(left) > max {
			max = len(left)
		}
		// default annotation (like pflag)
		dv := f.DefValue
		isZero := dv == "" || dv == "0" || dv == "false" || dv == "[]"
		if !isZero {
			if f.Value.Type() == "string" {
				usage += fmt.Sprintf(" (default %q)", dv)
			} else {
				usage += fmt.Sprintf(" (default %s)", dv)
			}
		}
		if len(f.Deprecated) != 0 {
			usage += fmt.Sprintf(" (DEPRECATED: %s)", f.Deprecated)
		}
		entries = append(entries, entry{left, usage})
	})
	col := max + 3
	var b strings.Builder
	// header line
	hdr := "Short   Long"
	b.WriteString(hdr)
	b.WriteString(strings.Repeat(" ", col-len(hdr)))
	b.WriteString("Purpose\n")
	for _, e := range entries {
		b.WriteString(e.left)
		b.WriteString(strings.Repeat(" ", col-len(e.left)))
		b.WriteString(e.right)
		b.WriteString("\n")
	}
	return b.String()
}

func customHelp(cmd *cobra.Command, args []string) {
	out := cmd.OutOrStdout()
	long := cmd.Long
	if long == "" {
		long = cmd.Short
	}
	if long != "" {
		fmt.Fprintf(out, "%s\n\n", strings.TrimRight(long, "\n"))
	}
	fmt.Fprintf(out, "Usage:\n  %s [flags] [FILE]...\n\n", cmd.CommandPath())
	fmt.Fprintf(out, "Flags:\n")
