var opts Options

var version = "dev"
var revision = "HEAD"

func flagUsagesCustom(fs *pflag.FlagSet) string {
	type entry struct{ left, right string }
	var entries []entry
	max := 0
	fs.SortFlags = true
	fs.VisitAll(func(f *pflag.Flag) {
		if f.Hidden {
			return
		}
		var left string
		if f.Shorthand != "" && f.ShorthandDeprecated == "" {
			left = fmt.Sprintf("  -%s, --%s", f.Shorthand, f.Name)
		} else {
			left = fmt.Sprintf("      --%s", f.Name)
		}
		varname, usage := pflag.UnquoteUsage(f)
		if varname != "" {
			left += " " + varname
		}
		switch f.Name {
		case "incsearch", "status-line", "wrap":
			left += "[=true|false]"
		}
		if len(left) > max {
			max = len(left)
		}
		// default annotation (like pflag)
		dv := f.DefValue
		isZero := dv == "" || dv == "0" || dv == "false" || dv == "[]"
		if !isZero {
			if f.Value.Type() == "string" {
				usage += fmt.Sprintf(" (default %q)", dv)
			} else {
				usage += fmt.Sprintf(" (default %s)", dv)
			}
		}
		if len(f.Deprecated) != 0 {
			usage += fmt.Sprintf(" (DEPRECATED: %s)", f.Deprecated)
		}
		entries = append(entries, entry{left, usage})
	})
	col := max + 3
	var b strings.Builder
	// header line
	hdr := "Short   Long"
	b.WriteString(hdr)
	b.WriteString(strings.Repeat(" ", col-len(hdr)))
	b.WriteString("Purpose\n")
	for _, e := range entries {
		b.WriteString(e.left)
		b.WriteString(strings.Repeat(" ", col-len(e.left)))
		b.WriteString(e.right)
		b.WriteString("\n")
	}
	return b.String()
}

func customHelp(cmd *cobra.Command, args []string) {
	out := cmd.OutOrStdout()
	long := cmd.Long
	if long == "" {
		long = cmd.Short
	}
	if long != "" {
		fmt.Fprintf(out, "%s\n\n", strings.TrimRight(long, "\n"))
	}
	fmt.Fprintf(out, "Usage:\n  %s [flags] [FILE]...\n\n", cmd.CommandPath())
	fmt.Fprintf(out, "Flags:\n")
	fmt.Fprint(out, flagUsagesCustom(cmd.Flags()))
}

func isTerminalFd(fd uintptr) bool {
	return term.IsTerminal(int(fd))
}

// nonTTYCopy handles the case where stdout is not a terminal (and not force-screen).
// It copies stdin, or the first file argument, to stdout verbatim.
func nonTTYCopy(args []string) error {
	// filter out empty file names (reference behaviour for "" arg)
	var files []string
	for _, a := range args {
		if a != "" {
			files = append(files, a)
		}
	}
	if len(files) == 0 {
		_, err := io.Copy(os.Stdout, os.Stdin)
		return err
	}
	f, err := os.Open(files[0])
	if err != nil {
		return err
	}
	defer f.Close()
	_, err = io.Copy(os.Stdout, f)
	return err
}

func runRoot(cmd *cobra.Command, args []string) error {
	// "Using config file" debug reporting (root only)
	debugMode := opts.Debug || cfg.Debug
	if debugMode {
		if cfgUsedFile != "" {
			fmt.Fprintf(os.Stderr, "Using config file: %s\n", cfgUsedFile)
		} else {
			fmt.Fprintf(os.Stderr, "config file not found\n")
		}
	}

	if opts.Version {
		fmt.Fprintf(cmd.OutOrStdout(), "ov version %s rev:%s\n", version, revision)
		return nil
	}
	if opts.HelpKey {
		fmt.Fprint(cmd.OutOrStdout(), helpKeyString())
		return nil
	}
	if opts.ListViewModes {
		for _, m := range listViewModes() {
			fmt.Fprintln(cmd.OutOrStdout(), m)
		}
		return nil
	}
	if opts.Completion != "" {
		switch opts.Completion {
		case "bash":
			return cmd.Root().GenBashCompletion(cmd.OutOrStdout())
		case "zsh":
			return cmd.Root().GenZshCompletion(cmd.OutOrStdout())
		case "fish":
			return cmd.Root().GenFishCompletion(cmd.OutOrStdout(), true)
		case "powershell":
			return cmd.Root().GenPowerShellCompletionWithDesc(cmd.OutOrStdout())
		default:
			return fmt.Errorf("requires one of the arguments bash/zsh/fish/powershell")
		}
	}

	// Non-terminal stdout: plain copy, unless --force-screen.
	if !isTerminalFd(os.Stdout.Fd()) && !opts.ForceScreen {
		// When stdin is a terminal and no file is given, the reference falls through
		// to the normal (pager) validation below, which yields "missing file".
		if !(len(args) == 0 && !opts.Exec && isTerminalFd(os.Stdin.Fd())) {
			return nonTTYCopy(args)
		}
	}

	return runPager(args)
}

