func parseSGRParams(s string) []string {
	if s == "" {
		return []string{"0"}
	}
	return strings.Split(s, ";")
}

// applySGR returns the new style after an SGR sequence with the given parameter string.
func applySGR(style, base tcell.Style, paramStr string) tcell.Style {
	// parameters separated by ';', sub-parameters by ':'.
	groups := strings.Split(paramStr, ";")
	if len(groups) == 1 && groups[0] == "" {
		groups = []string{"0"}
	}
	i := 0
	for i < len(groups) {
		g := groups[i]
		i++
		sub := strings.Split(g, ":")
		code, err := strconv.Atoi(sub[0])
		if err != nil {
			if sub[0] == "" {
				code = 0
			} else {
				continue
			}
		}
		switch {
		case code == 0:
			style = base
		case code == 1:
			style = style.Bold(true)
		case code == 2:
			style = style.Dim(true)
		case code == 3:
			style = style.Italic(true)
		case code == 4:
			us := tcell.UnderlineStyleSolid
			if len(sub) > 1 {
				switch sub[1] {
				case "0":
					us = tcell.UnderlineStyleNone
				case "1":
					us = tcell.UnderlineStyleSolid
				case "2":
					us = tcell.UnderlineStyleDouble
				case "3":
					us = tcell.UnderlineStyleCurly
				case "4":
					us = tcell.UnderlineStyleDotted
				case "5":
					us = tcell.UnderlineStyleDashed
				}
			}
			style = style.Underline(us)
		case code == 5:
			style = style.Blink(true)
		case code == 7:
			style = style.Reverse(true)
		case code == 9:
			style = style.StrikeThrough(true)
		case code == 22:
			style = style.Bold(false).Dim(false)
		case code == 23:
			style = style.Italic(false)
		case code == 24:
			style = style.Underline(false)
		case code == 25:
			style = style.Blink(false)
		case code == 27:
			style = style.Reverse(false)
		case code == 29:
			style = style.StrikeThrough(false)
		case code >= 30 && code <= 37:
			style = style.Foreground(tcell.PaletteColor(code - 30))
		case code == 39:
			style = style.Foreground(tcell.ColorDefault)
		case code >= 40 && code <= 47:
			style = style.Background(tcell.PaletteColor(code - 40))
		case code == 49:
			style = style.Background(tcell.ColorDefault)
		case code >= 90 && code <= 97:
			style = style.Foreground(tcell.PaletteColor(code - 90 + 8))
		case code >= 100 && code <= 107:
			style = style.Background(tcell.PaletteColor(code - 100 + 8))
		case code == 38 || code == 48 || code == 58:
			// Extended color: parameters may be in sub (colon form) or following groups.
			var params []string
			if len(sub) > 1 {
				params = sub[1:]
				// colon form for truecolor may have an empty colorspace component: 38:2::r:g:b
				var filtered []string
				for _, p := range params {
					if p != "" {
						filtered = append(filtered, p)
					}
				}
				params = filtered
			} else {
				// consume following groups
				for i < len(groups) {
					params = append(params, groups[i])
					if groups[i] == "5" && len(params) >= 2 {
						break
					}
					if groups[i] == "2" && len(params) >= 4 {
						break
					}
					i++
					// break conditions handled after append; adjust below
					if len(params) >= 1 && params[0] == "5" && len(params) == 2 {
						break
					}
					if len(params) >= 1 && params[0] == "2" && len(params) == 4 {
						break
					}
				}
			}
			var col tcell.Color
			ok := false
			if len(params) >= 2 && params[0] == "5" {
				if n, err := strconv.Atoi(params[1]); err == nil {
					col = tcell.PaletteColor(n)
					ok = true
				}
			} else if len(params) >= 4 && params[0] == "2" {
				r1, e1 := strconv.Atoi(params[1])
				g1, e2 := strconv.Atoi(params[2])
				b1, e3 := strconv.Atoi(params[3])
				if e1 == nil && e2 == nil && e3 == nil {
					col = tcell.NewRGBColor(int32(r1), int32(g1), int32(b1))
					ok = true
				}
			}
			if ok {
				switch code {
				case 38:
					style = style.Foreground(col)
				case 48:
					style = style.Background(col)
				case 58:
					// underline color alone does not enable underline in the reference (es converter
					// appeared to drop it); still record color.
					style = style.Underline(col)
				}
			}
		}
	}
	return style
}

// parseLine converts a raw logical line into display cells.
func parseLine(raw string, tabWidth int, converter string, plainMode bool, bodyStyle tcell.Style, overStrike, overLine StyleCfg) ParsedLine {
	rawConverter := converter == "raw"
	var cells []Cell
	var plainRunes []rune

	cur := bodyStyle
	widthSoFar := 0

	addPlain := func(r rune) int {
		idx := len(plainRunes)
		plainRunes = append(plainRunes, r)
		return idx
	}

	appendCell := func(r rune, st tcell.Style, plainIdx int, w int) {
		if w == 0 {
			// combining char: attach to previous cell.
			if len(cells) > 0 {
				cells[len(cells)-1].Comb = append(cells[len(cells)-1].Comb, r)
				return
			}
			w = 1
			r = ' '
		}
		cells = append(cells, Cell{R: r, Style: st, Width: w, PlainIdx: plainIdx})
		widthSoFar += w
	}

	// byte index walk
	b := []byte(raw)
	pos := 0     // current cell insertion position (for backspace handling; == len(cells) normally)
	_ = pos

	for i := 0; i < len(b); {
		c0 := b[i]
		// Escape sequences
		if c0 == 0x1b {
			if rawConverter {
				// ESC shown as two cells "^["
				p := addPlain(0x1b)
				appendCell('^', cur, p, 1)
				appendCell('[', cur, p, 1)
				i++
				continue
			}
			if i+1 >= len(b) {
				break
			}
			switch b[i+1] {
			case '[': // CSI
				j := i + 2
				for j < len(b) && !(b[j] >= 0x40 && b[j] <= 0x7e) {
					j++
				}
				if j >= len(b) {
					i = len(b)
					continue
				}
				final := b[j]
				params := string(b[i+2 : j])
				if final == 'm' && !plainMode {
					cur = applySGR(cur, bodyStyle, params)
				}
				i = j + 1
				continue
			case ']': // OSC ... BEL or ESC \
				j := i + 2
				end := -1
				endLen := 0
				for j < len(b) {
					if b[j] == 0x07 {
						end = j
						endLen = 1
						break
					}
					if b[j] == 0x1b && j+1 < len(b) && b[j+1] == '\\' {
						end = j
						endLen = 2
						break
					}
					j++
				}
				var content string
				if end == -1 {
					content = string(b[i+2:])
					i = len(b)
				} else {
					content = string(b[i+2 : end])
					i = end + endLen
				}
				if !plainMode {
					// OSC 8 hyperlink: 8;id;uri
					if strings.HasPrefix(content, "8;") {
						parts := strings.SplitN(content, ";", 3)
						url := ""
						if len(parts) == 3 {
							url = parts[2]
						}
						if url != "" {
							cur = cur.Url(url)
						} else {
							cur = cur.Url("")
						}
					}
				}
				continue
			case '(', ')', '*', '+', '%', '#':
				// charset etc: skip escape + intermediate + one final char
				i += 2
				for i < len(b) && b[i] >= 0x20 && b[i] <= 0x2f {
					i++
				}
				if i < len(b) {
					i++
				}
				continue
			default:
				// two-char escape
				i += 2
				continue
			}
		}

		// decode one rune
		r, size := utf8.DecodeRune(b[i:])
		if r == utf8.RuneError && size == 1 {
			r = '?'
		}
		i += size

		switch r {
		case '\r':
			continue
		case '\b':
			// move insertion back one cell; handled by marking next char via a small trick:
			// we process by popping behaviour in the next iteration using pendingBS flag.
			pendingBackspaces++
			continue
		case '\t':
			p := addPlain('\t')
			if tabWidth < 0 {
				appendCell('\\', cur, p, 1)
				appendCell('t', cur, p, 1)
			} else if tabWidth > 0 {
				n := tabWidth - (widthSoFar % tabWidth)
				for k := 0; k < n; k++ {
					c := Cell{R: ' ', Style: cur, Width: 1, PlainIdx: p, TabPart: k > 0}
					cells = append(cells, c)
					widthSoFar++
				}
			}
			continue
		}

		if r < 0x20 || r == 0x7f {
			p := addPlain(r)
			appendCell(' ', cur, p, 1)
			continue
		}

		// Overstrike handling if previous characters included backspace(s).
		if pendingBackspaces > 0 {
			pendingBackspaces--
			if len(cells) > 0 {
				target := &cells[len(cells)-1]
				existing := target.R
				if existing == '_' && r != '_' {
					target.R = r
					target.Style = overLine.applyTo(cur)
					plainRunes[target.PlainIdx] = r
				} else if r == existing {
					target.Style = overStrike.applyTo(cur)
				} else {
					target.R = r
					target.Style = cur
					plainRunes[target.PlainIdx] = r
				}
				if target.Width == 0 {
					target.Width = 1
				}
				continue
			}
		}

		p := addPlain(r)
		w := runewidth.RuneWidth(r)
		if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || r == 0x200d {
			w = 0
		}
		appendCell(r, cur, p, w)
	}

	// FirstCell mapping
	first := make([]int, len(plainRunes))
	for i := range first {
		first[i] = -1
	}
	for ci, c := range cells {
		if c.PlainIdx >= 0 && c.PlainIdx < len(first) && first[c.PlainIdx] == -1 {
			first[c.PlainIdx] = ci
		}
	}
	return ParsedLine{Cells: cells, Plain: string(plainRunes), PlainRunes: plainRunes, FirstCell: first}
}

var pendingBackspaces int

func cellsWidth(cells []Cell) int {
	w := 0
	for _, c := range cells {
		w += c.Width
	}
	return w
}
