)

type DocKind int

const (
	KindFile DocKind = iota
	KindStdin
	KindExecOut
	KindExecErr
	KindHelp
	KindLog
	KindFilter
	KindMem
)

type Document struct {
	mu          sync.RWMutex
	Kind        DocKind
	Name        string // display name without doc index
	FilePath    string
	Lines       []string
	NoFinalNL   bool // last line had no trailing newline
	RawOrig     []byte // original (decompressed) bytes, for exit-write-original / save
	General     General
