	WatchBaseLine int // line index where latest watch reload started

	// for follow on files: read offset handled by reloading file and comparing length.
	followEOF bool

	// Set when the document was created by following (message prefix handled globally)
	Caption string
}

type Seg struct {
	LineIdx  int // logical line index in Lines
	StartCell int
	SegNo    int
}

type Field struct {
	Start int // plain rune index
	End   int // exclusive
	DelimStart int
	DelimEnd int
}

func (d *Document) totalLines() int { return len(d.Lines) }

func (d *Document) displayName() string {
	if opts.Caption != "" {
		return opts.Caption
	}
	if d.Caption != "" {
		return d.Caption
	}
	return d.Name
}

// originalLineIndex maps a line index in this doc to its line number for display purposes:
// for normal docs identity; for filter docs map into parent.
func (d *Document) origLine(idx int) int {
	if d.LineMap != nil && idx >= 0 && idx < len(d.LineMap) {
		return d.LineMap[idx]
	}
	return idx
}

func splitLines(data []byte) ([]string, bool) {
	if len(data) == 0 {
		return nil, true
	}
	s := string(data)
	noNL := !strings.HasSuffix(s, "\n")
	lines := strings.Split(s, "\n")
	if !noNL {
		lines = lines[:len(lines)-1]
	}
	return lines, noNL
}

// maybeDecompress detects compression by magic bytes.
func maybeDecompress(data []byte) []byte {
	if opts.SkipExtract || len(data) < 4 {
		return data
	}
	out, ok := tryDecompress(data)
	if ok {
		return out
	}
	return data
}

func tryDecompress(data []byte) ([]byte, bool) {
	// gzip
	if len(data) >= 3 && data[0] == 0x1f && data[1] == 0x8b {
		r, err := gzip.NewReader(bytes.NewReader(data))
		if err != nil {
			return data, false
		}
		defer r.Close()
		out, err := io.ReadAll(r)
		if err != nil && len(out) == 0 {
			return data, false
		}
		return out, true
	}
	// bzip2
	if len(data) >= 4 && data[0] == 'B' && data[1] == 'Z' && data[2] == 'h' && data[3] >= '1' && data[3] <= '9' {
		r := bzip2.NewReader(bytes.NewReader(data))
		out, err := io.ReadAll(r)
		if err != nil && len(out) == 0 {
			return data, false
		}
		return out, true
	}
	// xz
	if len(data) >= 6 && data[0] == 0xfd && data[1] == '7' && data[2] == 'z' && data[3] == 'X' && data[4] == 'Z' && data[5] == 0x00 {
		if out, err := decompressXZ(data); err == nil {
			return out, true
		}
		return data, false
	}
	// zstd (magic 0xFD2FB528 little endian)
	if len(data) >= 4 && data[0] == 0x28 && data[1] == 0xb5 && data[2] == 0x2f && data[3] == 0xfd {
		if out, err := decompressZstd(data); err == nil {
			return out, true
		}
		return data, false
	}
	// zstd skippable frames 0x184D2A50..5F
	if len(data) >= 4 && data[0] == 0x50 && data[1] == 0x2a && data[2] == 0x4d && (data[3] >= 0x18 && data[3] <= 0x1f) {
		if out, err := decompressZstd(data); err == nil {
			return out, true
		}
		return data, false
	}
	// lz4 frame
	if len(data) >= 4 && data[0] == 0x04 && data[1] == 0x22 && data[2] == 0x4d && data[3] == 0x18 {
		if out, err := decompressLZ4(data); err == nil {
			return out, true
		}
		return data, false
	}
	return data, false
}

func newDocFromBytes(name string, kind DocKind, data []byte, gen General) *Document {
	dec := maybeDecompress(data)
	lines, noNL := splitLines(dec)
	d := &Document{
		Kind: kind, Name: name, Lines: lines, NoFinalNL: noNL, RawOrig: dec,
		General: gen,
	}
	if len(cfgMultiColors()) > 0 {
		d.MultiColors = cfgMultiColors()
	}
	return d
}

func cfgMultiColors() []string {
	// The CLI string-slice flag already split on commas.
	return opts.MultiColor
}

func (d *Document) reloadFromFile() error {
	if d.FilePath == "" {
		return fmt.Errorf("no file")
	}
	data, err := readFileBytesFollowName(d)
	if err != nil {
		return err
	}
	dec := maybeDecompress(data)
	lines, noNL := splitLines(dec)
	d.mu.Lock()
	d.Lines = lines
	d.NoFinalNL = noNL
	d.RawOrig = dec
	d.mu.Unlock()
	d.invalidate()
	return nil
}

func readFileBytesFollowName(d *Document) ([]byte, error) {
	return os.ReadFile(d.FilePath)
}

// readAllStdin reads stdin fully (used in pager mode).
func readStdinAll() ([]byte, error) {
	r := bufio.NewReader(os.Stdin)
	return io.ReadAll(r)
}
