package main

import (
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/gdamore/tcell/v2"
)

func (d *Document) invalidate() {
	d.parsed = nil
	d.display = nil
	d.fields = nil
	d.segs = nil
	d.WidthCols = nil
	d.segWidth = -1
}

func (d *Document) effectiveConverter() string {
	c := d.General.Converter
	if c != "es" && c != "raw" && c != "align" {
		// Unknown converters behave like es for display purposes.
		return c // parseLine treats only "raw" specially; align handled here only when ==align
	}
	return c
}

func (d *Document) bodyStyleNow() tcell.Style {
	st := tcell.StyleDefault
	return d.General.Style.Body.applyTo(st)
}

func (d *Document) ensureParsed() {
	if d.parsed != nil {
		return
	}
	d.bodyStyle = d.bodyStyleNow()
	conv := d.General.Converter
	d.parsed = make([]ParsedLine, len(d.Lines))
	for i, ln := range d.Lines {
		d.parsed[i] = parseLine(ln, d.General.TabWidth, conv, d.General.Plain, d.bodyStyle, cfg.StyleOverStrike, cfg.StyleOverLine)
	}
	d.display = nil
	d.fields = nil
	d.computeWidthCols()
	if conv == "align" {
		d.buildAlign()
	}
}

// displayCells returns cells for line i (aligned if applicable).
func (d *Document) lineCells(i int) []Cell {
	if d.display != nil {
		return d.display[i]
	}
	return d.parsed[i].Cells
}

func delimRunes(s string) []rune {
	if s == "\\t" {
		return []rune{'\t'}
	}
	return []rune(s)
}

// delimiterPattern parses a delimiter string that may be a /regexp/ form.
func splitFieldsRegex(plain []rune, re *regexp.Regexp) []Field {
	s := string(plain)
	locs := re.FindAllStringIndex(s, -1)
	if len(locs) == 0 {
		return nil
	}
	// convert byte offsets to rune offsets
	byteToRune := make([]int, len(s)+1)
	ri := 0
	for bi := range s {
		byteToRune[bi] = ri
		ri++
	}
	byteToRune[len(s)] = ri
	var fields []Field
	start := 0
	for _, loc := range locs {
		ds := byteToRune[loc[0]]
		de := byteToRune[loc[1]]
		if de == ds {
			continue
		}
		fields = append(fields, Field{Start: start, End: ds, DelimStart: ds, DelimEnd: de})
		start = de
	}
	fields = append(fields, Field{Start: start, End: len(plain), DelimStart: -1, DelimEnd: -1})
	return fields
}

// computeFieldsFor splits a line (by plain runes) with the document's delimiter.
func computeFieldsFor(plain []rune, delim string) []Field {
	if delim == "" {
		return nil
	}
	// /regexp/ form (seen in delimiter candidates)
	if len(delim) >= 2 && strings.HasPrefix(delim, "/") && strings.HasSuffix(delim, "/") {
		re, err := regexp.Compile(delim[1 : len(delim)-1])
		if err == nil {
			return splitFieldsRegex(plain, re)
		}
		return nil
	}
	dr := delimRunes(delim)
	if len(dr) == 0 {
		return nil
	}
	var fields []Field
	start := 0
	i := 0
	inQuote := false
	found := false
	matchDelim := func(pos int) bool {
		if pos+len(dr) > len(plain) {
			return false
		}
		for k, r := range dr {
			if plain[pos+k] != r {
				return false
			}
		}
		return true
	}
	for i < len(plain) {
		atStart := i == start
		if inQuote {
			if plain[i] == '"' {
				if i+1 < len(plain) && plain[i+1] == '"' {
					i += 2
					continue
				}
				inQuote = false
				i++
				continue
			}
			i++
			continue
		}
		if plain[i] == '"' && atStart {
			inQuote = true
			i++
			continue
		}
		if matchDelim(i) {
			fields = append(fields, Field{Start: start, End: i, DelimStart: i, DelimEnd: i + len(dr)})
			i += len(dr)
			start = i
			found = true
			continue
		}
		i++
	}
	if !found {
		return nil
	}
	fields = append(fields, Field{Start: start, End: len(plain), DelimStart: -1, DelimEnd: -1})
	return fields
}

func (d *Document) fieldsForLine(i int) []Field {
	if i < 0 || i >= len(d.parsed) {
		return nil
	}
	if d.General.ColumnWidth {
		return d.widthFieldsForLine(i)
	}
	return computeFieldsFor(d.parsed[i].PlainRunes, d.General.ColumnDelimiter)
}

// cellVisualX returns the starting X of each cell (and total width).
func cellXs(cells []Cell) ([]int, int) {
	xs := make([]int, len(cells))
	x := 0
	for i, c := range cells {
		xs[i] = x
		x += c.Width
	}
	return xs, x
}

func (d *Document) computeWidthCols() {
	type tok struct{ start, end int }
	var allToks [][]tok
	maxCols := 0
	for li := range d.parsed {
		cells := d.parsed[li].Cells
		xs, _ := cellXs(cells)
		var toks []tok
		inTok := false
		var cur tok
		for ci, c := range cells {
			isSpace := c.R == ' '
			if !isSpace && !inTok {
				inTok = true
				cur = tok{start: xs[ci]}
			}
			if isSpace && inTok {
				cur.end = xs[ci]
				toks = append(toks, cur)
				inTok = false
			}
		}
		if inTok {
			x := 0
			if len(cells) > 0 {
				x = xs[len(cells)-1] + cells[len(cells)-1].Width
			}
			cur.end = x
			toks = append(toks, cur)
		}
		allToks = append(allToks, toks)
		if len(toks) > maxCols {
			maxCols = len(toks)
		}
	}
	if maxCols <= 1 {
		d.WidthCols = nil
		return
	}
	var seps []int
	for col := 0; col < maxCols-1; col++ {
		maxEnd := -1
		minNext := -1
		for _, toks := range allToks {
			if len(toks) > col+1 {
				if toks[col].end > maxEnd {
					maxEnd = toks[col].end
				}
				if minNext == -1 || toks[col+1].start < minNext {
					minNext = toks[col+1].start
				}
			}
		}
		if maxEnd < 0 {
			continue
		}
		sep := minNext - 1
		if sep < 0 {
			sep = maxEnd
		}
		seps = append(seps, sep)
	}
	d.WidthCols = seps
}

func (d *Document) widthFieldsForLine(li int) []Field {
	if len(d.WidthCols) == 0 {
		return nil
	}
	cells := d.parsed[li].Cells
	xs, total := cellXs(cells)
	_ = total
	// Actual separators: a space cell at or after each boundary.
	var fields []Field
	prevPlain := 0
	prevX := 0
	plainLen := len(d.parsed[li].PlainRunes)
	for _, b := range d.WidthCols {
		sepCell := -1
		for ci, c := range cells {
			if xs[ci] >= b && c.R == ' ' {
				sepCell = ci
				break
			}
		}
		var endPlain int
		if sepCell == -1 {
			endPlain = plainLen
		} else {
			endPlain = cells[sepCell].PlainIdx
		}
		_ = prevX
		f := Field{Start: prevPlain, End: endPlain, DelimStart: endPlain, DelimEnd: endPlain + 1}
		if sepCell == -1 {
			f.DelimStart = -1
			f.DelimEnd = -1
		}
		fields = append(fields, f)
		prevPlain = endPlain + 1
		if sepCell == -1 {
			prevPlain = plainLen
		}
		prevX = b + 1
	}
	fields = append(fields, Field{Start: prevPlain, End: plainLen, DelimStart: -1, DelimEnd: -1})
	// A line with no spaces at all has no fields (matches reference 'column not found').
	hasSpace := false
	for _, c := range cells {
		if c.R == ' ' {
			hasSpace = true
			break
		}
	}
	if !hasSpace {
		return nil
	}
	return fields
}

func fieldVisualWidth(cells []Cell, f Field) int {
	w := 0
	for _, c := range cells {
		if c.PlainIdx >= f.Start && c.PlainIdx < f.End {
			w += c.Width
		}
	}
	return w
}

func (d *Document) buildAlign() {
	// compute fields per line and max widths
	perLine := make([][]Field, len(d.parsed))
	maxCols := 0
	for i := range d.parsed {
		perLine[i] = computeFieldsFor(d.parsed[i].PlainRunes, d.General.ColumnDelimiter)
		if len(perLine[i]) > maxCols {
			maxCols = len(perLine[i])
		}
	}
	maxW := make([]int, maxCols)
	for i := range d.parsed {
		for ci, f := range perLine[i] {
			w := fieldVisualWidth(d.parsed[i].Cells, f)
			if w > maxW[ci] {
				maxW[ci] = w
			}
		}
	}
	shrinkRune := firstRune(cfg.ShrinkChar, '…')
	_ = shrinkRune
	d.display = make([][]Cell, len(d.parsed))
	for i := range d.parsed {
		pl := d.parsed[i]
		fields := perLine[i]
		if len(fields) == 0 {
			d.display[i] = pl.Cells
			continue
		}
		var out []Cell
		byPlain := map[int][]Cell{}
		for _, c := range pl.Cells {
			byPlain[c.PlainIdx] = append(byPlain[c.PlainIdx], c)
		}
		emitRange := func(start, end int) {
			for p := start; p < end; p++ {
				out = append(out, byPlain[p]...)
			}
		}
		for ci, f := range fields {
			emitRange(f.Start, f.End)
			if f.DelimStart >= 0 {
				w := fieldVisualWidth(pl.Cells, f)
				pad := maxW[ci] - w
				padPlain := f.End - 1
				if f.End == f.Start {
					padPlain = f.DelimStart
				}
				for k := 0; k < pad; k++ {
					out = append(out, Cell{R: ' ', Style: d.bodyStyle, Width: 1, PlainIdx: padPlain})
				}
				emitRange(f.DelimStart, f.DelimEnd)
			}
		}
		d.display[i] = out
	}
}

func firstRune(s string, def rune) rune {
	for _, r := range s {
		return r
	}
	return def
}

func (d *Document) skipCount() int {
	if d.General.SkipLines > 0 {
		return d.General.SkipLines
	}
	return 0
}

// ensureSegments builds the display segment list for the given content width.
func (d *Document) ensureSegments(contentWidth int) {
	if d.segs != nil && d.segWidth == contentWidth {
		return
	}
	d.ensureParsed()
	if contentWidth < 1 {
		contentWidth = 1
	}
	d.segWidth = contentWidth
	skip := d.skipCount()
	var segs []Seg
	segStart := make([]int, len(d.Lines))
	for i := range segStart {
		segStart[i] = -1
	}
	for li := skip; li < len(d.Lines); li++ {
		cells := d.lineCells(li)
		segStart[li] = len(segs)
		if !d.General.WrapMode || len(cells) == 0 {
			segs = append(segs, Seg{LineIdx: li, StartCell: 0, SegNo: 0})
			continue
		}
		start := 0
		w := 0
		segNo := 0
		for ci, c := range cells {
			if w+c.Width > contentWidth && ci > start {
				segs = append(segs, Seg{LineIdx: li, StartCell: start, SegNo: segNo})
				segNo++
				start = ci
				w = 0
			}
			w += c.Width
		}
		segs = append(segs, Seg{LineIdx: li, StartCell: start, SegNo: segNo})
	}
	d.segs = segs
	d.segStartByLine = segStart
	// header segs count: segments whose line < skip+header
	hdr := 0
	limit := skip + d.General.Header
	if d.General.Header > 0 {
		for _, s := range segs {
			if s.LineIdx < limit {
				hdr++
			} else {
				break
			}
		}
	}
	d.headerSegs = hdr
}

func (d *Document) firstSegOfLine(lineIdx int) int {
	if lineIdx < 0 {
		return lineIdx // allow negative offsets
	}
	if d.segStartByLine != nil && lineIdx < len(d.segStartByLine) {
		if v := d.segStartByLine[lineIdx]; v >= 0 {
			return v
		}
		// line before skip: find first seg at/after it
	}
	// search
	for i, s := range d.segs {
		if s.LineIdx >= lineIdx {
			return i
		}
	}
	return len(d.segs)
}

// segmentLine returns the logical line number (0-based) for a seg index, handling out-of-range.
func (d *Document) segLine(segIdx int) int {
	if len(d.segs) == 0 {
		// status for empty docs
		if d.General.SkipLines > 0 || d.General.Header != 0 {
			return d.General.SkipLines + d.General.Header
		}
		return 0
	}
	if segIdx < 0 {
		// align so segIdx == -1 gives the line just before the first seg
		return d.segs[0].LineIdx + segIdx
	}
	if segIdx >= len(d.segs) {
		extra := segIdx - (len(d.segs) - 1)
		return d.segs[len(d.segs)-1].LineIdx + extra
	}
	return d.segs[segIdx].LineIdx
}

// searcher

type Searcher struct {
	Pattern  string
	Regexp   bool
	CaseSensitive bool
	Smart    bool
	re       *regexp.Regexp
	valid    bool
}

func effectiveCase(pattern string, caseSens, smart bool) bool {
	if caseSens {
		return true
	}
	if smart {
		for _, r := range pattern {
			if r >= 'A' && r <= 'Z' {
				return true
			}
			// unicode uppercase
			if isUpperRune(r) {
				return true
			}
		}
	}
	return false
}

func isUpperRune(r rune) bool {
	return r >= 'A' && r <= 'Z' || (r > 127 && strconv.IsPrint(r) && strings.ToUpper(string(r)) == string(r) && strings.ToLower(string(r)) != string(r))
}

func newSearcher(pattern string, regexpMode, caseSens, smart bool) *Searcher {
	s := &Searcher{Pattern: pattern, Regexp: regexpMode, CaseSensitive: caseSens, Smart: smart, valid: true}
	if regexpMode && pattern != "" {
		p := pattern
		if !effectiveCase(pattern, caseSens, smart) {
			p = "(?i)" + p
		}
		re, err := regexp.Compile(p)
		if err != nil {
			s.valid = false
		} else {
			s.re = re
		}
	}
	return s
}

// findMatches returns [start,end) rune index pairs in the plain string.
func (s *Searcher) findMatches(plain string) [][2]int {
	if s == nil || s.Pattern == "" || !s.valid {
		return nil
	}
	if s.Regexp {
		if s.re == nil {
			return nil
		}
		locs := s.re.FindAllStringIndex(plain, -1)
		if len(locs) == 0 {
			return nil
		}
		out := make([][2]int, 0, len(locs))
		for _, loc := range locs {
			out = append(out, [2]int{len([]rune(plain[:loc[0]])), len([]rune(plain[:loc[1]]))})
		}
		return out
	}
	// literal
	if effectiveCase(s.Pattern, s.CaseSensitive, s.Smart) {
		var out [][2]int
		idx := 0
		pr := []rune(s.Pattern)
		plainR := []rune(plain)
		for {
			j := indexRunes(plainR[idx:], pr)
			if j < 0 {
				break
			}
			start := idx + j
			out = append(out, [2]int{start, start + len(pr)})
			idx = start + maxInt(1, len(pr))
			if idx > len(plainR) {
				break
			}
		}
		return out
	}
	lowerPlain := strings.ToLower(plain)
	lowerPat := strings.ToLower(s.Pattern)
	var out [][2]int
	plainR := []rune(lowerPlain)
	pr := []rune(lowerPat)
	idx := 0
	for {
		j := indexRunes(plainR[idx:], pr)
		if j < 0 {
			break
		}
		start := idx + j
		out = append(out, [2]int{start, start + len(pr)})
		idx = start + maxInt(1, len(pr))
		if idx > len(plainR) {
			break
		}
	}
	return out
}

func indexRunes(hay, needle []rune) int {
	if len(needle) == 0 {
		return 0
	}
	for i := 0; i+len(needle) <= len(hay); i++ {
		ok := true
		for k := range needle {
			if hay[i+k] != needle[k] {
				ok = false
				break
			}
		}
		if ok {
			return i
		}
	}
	return -1
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}
func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

// findForward searches lines from fromLine.
func (d *Document) findLine(s *Searcher, fromLine int, forward bool, inclusive bool) int {
	d.ensureParsed()
	if forward {
		start := fromLine
		if !inclusive {
			start++
		}
		for i := start; i < len(d.parsed); i++ {
			if i < 0 {
				continue
			}
			if len(s.findMatches(d.parsed[i].Plain)) > 0 {
				return i
			}
		}
		return -1
	}
	start := fromLine
	if !inclusive {
		start--
	}
	for i := start; i >= 0; i-- {
		if i >= len(d.parsed) {
			continue
		}
		if len(s.findMatches(d.parsed[i].Plain)) > 0 {
			return i
		}
	}
	return -1
}

// sorted copy helper
func sortedStrings(in []string) []string {
	out := append([]string(nil), in...)
	sort.Strings(out)
	return out
}
