func (p *Pager) bodyRows() int {
	h := p.height
	if h == 0 {
		_, h = p.screen.Size()
	}
	rows := h
	if p.statusLineEnabled() && h > 1 {
		rows--
	}
	if rows < 1 {
		rows = 1
	}
	return rows
}

func (p *Pager) statusLineEnabled() bool {
	// Per-flag; document toggles are handled with a pager-level flag.
	return p.statusLine
}

// endTopSeg computes End position (may be negative, matching reference).
func (p *Pager) endTopSeg(d *Document) int {
	avail := p.availableRows(d)
	if avail < 1 {
		avail = 1
	}
	return len(d.segs) - avail + 1
}

// availableRows = rows for body segments after ruler/header sections.
