	// (No-op placeholder.)
	_ = d
}

func (p *Pager) moveTop(d *Document, delta int) {
	endTop := p.endTopSeg(d)
	top := d.TopSeg
	if delta > 0 {
		if top >= endTop {
			// Still normalise a negative top which is > endTop? Down on a tiny
			// doc after End does nothing in the reference.
			return
		}
		top += delta
		if top > endTop {
			top = endTop
		}
	} else if delta < 0 {
		top += delta
		if top < d.headerSegs {
			top = d.headerSegs
			// For tiny doc after End (top negative), Up goes to the start.
			if d.TopSeg < d.headerSegs {
				top = d.headerSegs
			}
		}
	}
	d.TopSeg = top
}

func (p *Pager) goTop(d *Document) {
	d.TopSeg = d.headerSegs
	if d.General.SkipLines < 0 {
		d.TopSeg = d.General.SkipLines
	}
	if d.General.Header < 0 {
		d.TopSeg = d.General.Header
	}
}

func (p *Pager) goBottom(d *Document) {
	d.TopSeg = p.endTopSeg(d)
}

// moveToLine sets TopSeg so the given logical line is the first body line,
