func (p *Pager) moveToLine(d *Document, lineIdx int, useJump bool) {
	seg := d.firstSegOfLine(lineIdx)
	if useJump {
		seg -= p.jumpOffsetSegs(d, lineIdx)
	}
	if seg < d.headerSegs {
		// When a jump target would place the top into the header area at the
		// very start of the file, the reference still allows small tops for
		// search landings near the top (see -j tests with no header).
		// With a header, clamp to first body segment.
		if d.General.Header > 0 {
			seg = d.headerSegs
		}
	}
	d.TopSeg = seg
}

func (p *Pager) jumpOffsetSegs(d *Document, targetLine int) int {
	jt := d.General.JumpTarget
	if jt == "" {
		return 0
	}
	return jumpOffset(jt, p.bodyRows(), d, targetLine, p)
}

func jumpOffset(jt string, bodyRows int, d *Document, targetLine int, p *Pager) int {
	jt = strings.TrimSpace(jt)
	if jt == "" {
		return 0
	}
	if jt == "section" {
		// Offset so the section start line lands at the top.
		if d == nil || p == nil {
			return 1
		}
		sec := p.sectionStartLineFor(d, targetLine)
		if sec < 0 {
			return 1
		}
		off := 0
		for _, s := range d.segs {
			if s.LineIdx >= sec && s.LineIdx < targetLine {
				off++
			}
		}
		return off
	}
	if strings.HasSuffix(jt, "%") {
		num := strings.TrimSuffix(jt, "%")
		if v, err := parseFloat(num); err == nil {
			return int(float64(bodyRows) * v / 100.0)
		}
		return 0
	}
	if strings.HasPrefix(jt, ".") || strings.HasPrefix(jt, "-.") {
		if v, err := parseFloat(jt); err == nil {
			if v < 0 {
				// fractional from bottom handled below via negative ints? ignore
				return 0
			}
			return int(float64(bodyRows) * v)
		}
		return 0
	}
	if n, err := parseIntStrict(jt); err == nil {
		if n >= 0 {
			return n
		}
		// negative: from bottom. -1 => match on last row.
		return bodyRows + n
	}
	return 0
}

func parseFloat(s string) (float64, error) {
	var f float64
	_, err := fmt.Sscan(s, &f)
	if err != nil {
		// Sscan of ".5" works; keep simple fallback
		return 0, err
	}
	return f, nil
}

func parseIntStrict(s string) (int, error) {
	var n int
	_, err := fmt.Sscan(s, &n)
	if err != nil {
		return 0, err
	}
	// ensure whole string is an int representation
	if fmt.Sprintf("%d", n) != s {
		// allow leading + / zeros via strconv
		v, err2 := strconvAtoi(s)
		if err2 != nil {
			return 0, err2
		}
		return v, nil
	}
	return n, nil
}

func strconvAtoi(s string) (int, error) {
	neg := false
	i := 0
	if strings.HasPrefix(s, "-") {
		neg = true
		i = 1
	} else if strings.HasPrefix(s, "+") {
		i = 1
	}
	if i >= len(s) {
		return 0, fmt.Errorf("invalid")
	}
	n := 0
	for ; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, fmt.Errorf("invalid")
		}
		n = n*10 + int(s[i]-'0')
	}
	if neg {
		n = -n
	}
	return n, nil
}

func (p *Pager) setMessage(d *Document, msg string) {
	if d != nil {
		d.Message = msg
	}
}

func (p *Pager) clearMessage(d *Document) {
	if d != nil {
		d.Message = ""
	}
}

