func (p *Pager) sectionHeaderLines(d *Document) []int {
	if d == nil || !d.General.SectionHeader {
		return nil
	}
	topLine := d.segLine(d.TopSeg)
	sec := p.sectionStartLineFor(d, topLine)
	if sec < 0 || topLine <= sec {
		return nil
	}
	n := d.General.SectionHeaderNum
	if n < 1 {
		n = 1
	}
	var out []int
	for i := sec; i < sec+n && i < len(d.Lines); i++ {
		out = append(out, i)
	}
	return out
}

func (p *Pager) sectionHeaderSegCount(d *Document) int {
	lines := p.sectionHeaderLines(d)
	if len(lines) == 0 {
		return 0
	}
	// Count segments for these lines in d.segs
	set := map[int]bool{}
	for _, l := range lines {
		set[l] = true
	}
	n := 0
	for _, s := range d.segs {
		if set[s.LineIdx] {
			n++
		}
	}
	return n
}

func (p *Pager) isSectionLine(d *Document, lineIdx int) bool {
	re := p.sectionRegexp(d)
	if re == nil || lineIdx < 0 || lineIdx >= len(d.parsed) {
		return false
	}
	return re.MatchString(d.parsed[lineIdx].Plain)
}
