func (p *Pager) makeDoc(name string, kind DocKind, data []byte) *Document {
	gen := p.initialGeneral()
	d := newDocFromBytes(name, kind, data, gen)
	d.EOF = true
	d.ensureParsed()
	// initial top = first body segment
	// Segments need a width; use 80 as a provisional width, rebuilt at draw with real width.
	d.ensureSegments(80)
	d.TopSeg = d.headerSegs
	if d.General.SkipLines < 0 {
		d.TopSeg = d.General.SkipLines
	}
	if d.General.Header < 0 {
		d.TopSeg = d.General.Header
	}
	d.ColumnCursor = initialColumnCursor(d)
	if opts.FollowMode || opts.FollowAll || opts.FollowSection || opts.FollowName {
		d.Follow = true
	}
	if opts.FollowSection {
		d.FollowSection = true
	}
	return d
}

func initialColumnCursor(d *Document) int {
	if d.General.HeaderColumn > 0 {
		return d.General.HeaderColumn
	}
	// If the first field of the first non-empty line is empty (delimiter at 0), start at 1.
	d.ensureParsed()
	skip := d.skipCount()
	for i := skip; i < len(d.parsed) && i < skip+50; i++ {
		f := d.fieldsForLine(i)
		if len(f) > 1 && f[0].Start == f[0].End {
			return 1
		}
		if len(f) > 0 {
			return 0
		}
	}
	return 0
}

func (p *Pager) buildDocs(args []string) error {
	if opts.Exec {
		if len(args) == 0 {
			return fmt.Errorf("no arguments to execute")
		}
		return p.buildExecDocs(args)
	}
	if len(args) > 0 {
		var firstOpenErr error
		for _, path := range args {
			fi, serr := os.Stat(path)
			if serr != nil {
				continue
			}
			if fi.IsDir() {
				continue
			}
			data, err := os.ReadFile(path)
			if err != nil {
				if firstOpenErr == nil {
					firstOpenErr = err
				}
				continue
			}
			d := p.makeDoc(path, KindFile, data)
			d.FilePath = path
			d.Seekable = fi.Mode().IsRegular()
			d.lastModSize = fi.Size()
			d.lastModTimeUnixNano = fi.ModTime().UnixNano()
			p.docs = append(p.docs, d)
			p.logf("open [%d]%s", len(p.docs)-1, path)
			if cfg.Debug {
				p.logf("%s:Update EndNum:%d", path, len(d.Lines))
			}
		}
		if len(p.docs) == 0 {
			if len(args) == 1 {
				fi, serr := os.Stat(args[0])
				if serr != nil {
					return fmt.Errorf("'%s' not found", args[0])
				}
				if fi.IsDir() {
					return fmt.Errorf("'%s' is a directory", args[0])
				}
				if firstOpenErr != nil {
					return firstOpenErr
				}
				return fmt.Errorf("'%s' not found", args[0])
			}
			return fmt.Errorf("missing file")
		}
		return nil
	}
	// stdin
	if isTerminalFd(os.Stdin.Fd()) {
		return fmt.Errorf("missing file")
	}
	d := p.makeDoc("(STDIN)", KindStdin, nil)
	d.EOF = false
	d.Lines = nil
	d.invalidate()
	p.docs = append(p.docs, d)
	p.logf("open [0](STDIN)")
	go p.readStreamDoc(d, os.Stdin)
	return nil
}

// readStreamDoc streams lines into d from r (stdin / pipes). If the stream is
// compressed (magic at start) it buffers everything and decompresses at EOF.
func (p *Pager) readStreamDoc(d *Document, r io.Reader) {
	br := bufio.NewReader(r)
	// Peek for magic.
	peek, _ := br.Peek(6)
	compressed := false
	if !opts.SkipExtract && len(peek) >= 4 {
		if _, ok := tryDecompressMagic(peek); ok {
			compressed = true
		}
	}
	if compressed {
		data, _ := io.ReadAll(br)
		dec := maybeDecompress(data)
		lines, noNL := splitLines(dec)
		d.mu.Lock()
		d.Lines = lines
		d.NoFinalNL = noNL
		d.RawOrig = dec
		d.EOF = true
		d.mu.Unlock()
		d.invalidate()
		p.postTick()
		return
	}
	var rawAll []byte
	for {
		chunk, err := br.ReadBytes('\n')
		if len(chunk) > 0 {
			rawAll = append(rawAll, chunk...)
			line := strings.TrimSuffix(string(chunk), "\n")
			d.mu.Lock()
			d.Lines = append(d.Lines, line)
			d.RawOrig = rawAll
			d.mu.Unlock()
			d.invalidate()
			p.postTick()
		}
		if err != nil {
			break
		}
	}
	d.mu.Lock()
	d.EOF = true
	d.mu.Unlock()
	d.invalidate()
	p.postTick()
}

func tryDecompressMagic(b []byte) ([]byte, bool) {
	// only used as a magic check; return ok=true if a known magic matches.
	if len(b) >= 2 && b[0] == 0x1f && b[1] == 0x8b {
		return nil, true
	}
	if len(b) >= 4 && b[0] == 'B' && b[1] == 'Z' && b[2] == 'h' {
		return nil, true
	}
	if len(b) >= 6 && b[0] == 0xfd && b[1] == '7' && b[2] == 'z' && b[3] == 'X' && b[4] == 'Z' {
		return nil, true
	}
	if len(b) >= 4 && b[0] == 0x28 && b[1] == 0xb5 && b[2] == 0x2f && b[3] == 0xfd {
		return nil, true
	}
	if len(b) >= 4 && b[0] == 0x04 && b[1] == 0x22 && b[2] == 0x4d && b[3] == 0x18 {
		return nil, true
	}
	return nil, false
}

func (p *Pager) postTick() {
	if p.screen != nil {
		_ = p.screen.PostEvent(&tickEvent{t: time.Now()})
	}
}

func (p *Pager) buildExecDocs(args []string) error {
	cmdName := args[0]
	gen := p.initialGeneral()
	outDoc := &Document{Kind: KindExecOut, Name: fmt.Sprintf("(%s)STDOUT", cmdName), General: cloneGeneral(gen), EOF: false}
	errDoc := &Document{Kind: KindExecErr, Name: fmt.Sprintf("(%s)STDERR", cmdName), General: cloneGeneral(gen), EOF: false}
	outDoc.ensureParsed()
	errDoc.ensureParsed()
	outDoc.ensureSegments(80)
	errDoc.ensureSegments(80)
	if len(cfgMultiColors()) > 0 {
		outDoc.MultiColors = cfgMultiColors()
		errDoc.MultiColors = cfgMultiColors()
	}
	p.docs = append(p.docs, outDoc, errDoc)
	p.logf("open [0]STDOUT")
	p.logf("open [1]STDERR")
	return p.startExec(args, outDoc, errDoc)
}

func (p *Pager) startExec(args []string, outDoc, errDoc *Document) error {
	c := exec.Command(args[0], args[1:]...)
	stdout, err := c.StdoutPipe()
	if err != nil {
		return fmt.Errorf("command start error: %w", err)
	}
	stderr, err := c.StderrPipe()
	if err != nil {
		return fmt.Errorf("command start error: %w", err)
	}
	// Feed the command our stdin if it is not a terminal-owned stream? In the
	// reference the command's stdin comes from the terminal/pty. Use /dev/null-ish default (nil).
	if err := c.Start(); err != nil {
		return fmt.Errorf("command start error: %w", err)
	}
	outDoc.ExecCmd = c
	errDoc.ExecCmd = c
	outDoc.ExecArgs = args
	errDoc.ExecArgs = args
	go p.readStreamDoc(outDoc, stdout)
	go p.readStreamDoc(errDoc, stderr)
	go func() {
		werr := c.Wait()
		outDoc.ExecDone = true
		errDoc.ExecDone = true
		if werr != nil {
			outDoc.ExecErr = werr
			errDoc.ExecErr = werr
		}
		p.postTick()
	}()
	return nil
}

func runPagerForCmd(cmd *cobra.Command, args []string) error {
	p := newPager(cmd)
	if err := p.buildDocs(args); err != nil {
		return err
	}

	// Screen setup.
	scr, err := tcell.NewScreen()
	if err != nil {
		// Fallback (like the reference) to a 256-color terminal description.
		os.Setenv("TERM", "screen-256color")
		scr, err = tcell.NewScreen()
		if err != nil {
			return fmt.Errorf("Screen.Init(): %w", err)
		}
	}
	if err := scr.Init(); err != nil {
		// Retry with fallback TERM once.
		os.Setenv("TERM", "screen-256color")
		scr2, err2 := tcell.NewScreen()
		if err2 != nil {
			return fmt.Errorf("Screen.Init(): %w", err)
		}
		scr = scr2
		if err := scr.Init(); err != nil {
			return fmt.Errorf("Screen.Init(): %w", err)
		}
	}
	p.screen = scr
	p.width, p.height = scr.Size()
	if p.mouseEnabled {
		scr.EnableMouse(tcell.MouseButtonEvents | tcell.MouseMotionEvents)
	}

	// Rebuild segments with the real width.
	for _, d := range p.docs {
		d.segs = nil
		d.segWidth = -1
		d.ensureSegments(p.contentWidthFor(d))
		// If TopSeg was never set past the header, normalise it.
		if d.TopSeg == 0 {
			d.TopSeg = d.headerSegs
			if d.General.SkipLines < 0 {
				d.TopSeg = d.General.SkipLines
			}
			if d.General.Header < 0 {
				d.TopSeg = d.General.Header
			}
		}
	}

	// Filters (CLI).
	if len(p.docs) > 0 && (opts.Filter != "" || opts.NonMatchFilter != "") {
		parent := p.docs[0]
		if opts.Filter != "" {
			fd := p.createFilter(parent, opts.Filter, false)
			p.insertDocAfter(parent, fd)
			p.cur = indexOfDoc(p.docs, fd)
		}
		if opts.NonMatchFilter != "" {
			fd := p.createFilter(parent, opts.NonMatchFilter, true)
			p.insertDocAfter(parent, fd)
			p.cur = indexOfDoc(p.docs, fd)
		}
	}

	// Quit-if-one-screen.
	if (opts.QuitIfOneScreen || cfg.QuitSmall) && !p.watchMode {
		if p.fitsOneScreen() {
			scr.Fini()
			d := p.curDoc()
				if d != nil {
					writeOriginalAll(d)
				}
			return nil
		}
	}

	// Initial pattern.
	if opts.Pattern != "" {
		p.searchPattern = opts.Pattern
		d := p.curDoc()
		if d != nil {
			d.Pattern = opts.Pattern
			p.applyInitialPattern(d)
		}
	}

	// Follow position.
	if opts.FollowMode || opts.FollowAll || opts.FollowSection || opts.FollowName {
		for _, d := range p.docs {
			d.ensureSegments(p.contentWidthFor(d))
			p.goBottom(d)
		}
		p.followAll = opts.FollowAll
	}

	if opts.SetTerminalTitle || cfg.SetTerminalTitle {
		if d := p.curDoc(); d != nil {
			scr.SetTitle(d.displayName())
		}
	}

	// EOF notification at start.
	if opts.NotifyEOF > 0 {
		if d := p.curDoc(); d != nil && d.EOF {
			d.Message = fmt.Sprintf("EOF reached: %s", d.Name)
			d.notifyCount++
		}
	}

	done := make(chan struct{})
	defer close(done)
	go func() {
		tk := time.NewTicker(120 * time.Millisecond)
		defer tk.Stop()
		for {
			select {
			case <-done:
				return
			case <-tk.C:
				p.postTick()
			}
		}
	}()

	p.lastWatch = time.Now()
	p.draw()
	for !p.quit {
		ev := scr.PollEvent()
		switch e := ev.(type) {
		case *tcell.EventResize:
			p.width, p.height = e.Size()
			scr.Sync()
			for _, d := range p.allDocs() {
				d.segs = nil
				d.segWidth = -1
			}
			p.draw()
		case *tcell.EventKey:
			p.handleKey(e)
			if !p.quit {
				p.draw()
			}
		case *tcell.EventMouse:
			p.handleMouse(e)
			if !p.quit {
				p.draw()
			}
		case *tcell.EventPaste:
			// runes arrive as key events; nothing special.
		case *tickEvent:
			p.onTick()
			if !p.quit {
				p.draw()
			}
		case *tcell.EventInterrupt:
			p.draw()
		}
	}

	// Capture exit-write output before Fini (positions are current).
	outText := p.buildExitOutput()
	scr.Fini()
	if outText != "" {
		fmt.Fprint(os.Stdout, outText)
	} else if opts.ForceScreen && !isTerminalFd(os.Stdout.Fd()) {
		if d := p.curDoc(); d != nil {
			writeOriginalAll(d)
		}
	}
	// Report exec wait errors like the reference (via the std logger).
	seen := map[*exec.Cmd]bool{}
	for _, d := range p.docs {
		if d.ExecCmd != nil && !seen[d.ExecCmd] {
			seen[d.ExecCmd] = true
			if d.ExecErr != nil {
				log.Printf("pty wait: %s", d.ExecErr.Error())
			}
		}
	}
	return nil
}

func (p *Pager) allDocs() []*Document {
	out := append([]*Document(nil), p.docs...)
	if p.helpDoc != nil {
		out = append(out, p.helpDoc)
	}
	if p.logDoc != nil {
		out = append(out, p.logDoc)
	}
	return out
}

func indexOfDoc(docs []*Document, d *Document) int {
	for i, x := range docs {
		if x == d {
			return i
		}
	}
	return -1
}

func (p *Pager) insertDocAfter(after, nd *Document) {
	idx := indexOfDoc(p.docs, after)
	if idx < 0 {
		p.docs = append(p.docs, nd)
		return
	}
	p.docs = append(p.docs, nil)
	copy(p.docs[idx+2:], p.docs[idx+1:])
	p.docs[idx+1] = nd
}

func (p *Pager) fitsOneScreen() bool {
	d := p.curDoc()
	if d == nil {
		return false
	}
	if !d.EOF {
		return false
	}
	rows := p.bodyRows()
	return len(d.segs) <= rows && len(p.docs) == 1
}

func writeOriginalAll(d *Document) {
	if d.RawOrig != nil {
		_, _ = os.Stdout.Write(d.RawOrig)
		return
	}
	for _, ln := range d.Lines {
		fmt.Fprintln(os.Stdout, ln)
	}
}

func (p *Pager) applyInitialPattern(d *Document) {
	s := newSearcher(p.searchPattern, p.regexpSearch, p.caseSensitive, p.smartCase)
	startLine := d.segLine(d.TopSeg)
	found := d.findLine(s, startLine, true, true)
	if found < 0 {
		d.Message = fmt.Sprintf("search:not found:%s", p.searchPattern)
		return
	}
	p.moveToLine(d, found, true)
}

func (p *Pager) createFilter(parent *Document, pattern string, negate bool) *Document {
	s := newSearcher(pattern, p.regexpSearch, p.caseSensitive, p.smartCase)
	var lines []string
	var lineMap []int
	parent.ensureParsed()
	for i := range parent.Lines {
		matched := len(s.findMatches(parent.parsed[i].Plain)) > 0
		if matched != negate {
			lines = append(lines, parent.Lines[i])
			lineMap = append(lineMap, i)
		}
	}
	namePat := pattern
	if negate {
		namePat = "!" + pattern
	}
	fd := &Document{
		Kind:    KindFilter,
		Name:    fmt.Sprintf("filter:%s", namePat),
		Lines:   lines,
		General: cloneGeneral(parent.General),
		Parent:  parent,
		LineMap: lineMap,
		EOF:     parent.EOF,
		Seekable: false,
		Pattern: pattern,
	}
	fd.Message = fmt.Sprintf("search:%s", namePat)
	fd.ensureParsed()
	fd.ensureSegments(p.contentWidthFor(fd))
	fd.TopSeg = fd.headerSegs
	fd.ColumnCursor = initialColumnCursor(fd)
	return fd
}
