func (p *Pager) draw() {
	if p.screen == nil {
		return
	}
	p.width, p.height = p.screen.Size()
	p.screen.Clear()
	d := p.curDoc()
	if d == nil {
		p.screen.Show()
		return
	}
	d.mu.RLock()
	// ensure segments for this width
	contentW := p.contentWidthFor(d)
	d.ensureSegments(contentW)
	d.mu.RUnlock()

	statusEnabled := p.statusLine && p.height > 1
	bodyRows := p.height
	if statusEnabled {
		bodyRows = p.height - 1
	}
	if bodyRows < 0 {
		bodyRows = 0
	}

	// sidebar
	contentX := 0
	if p.sidebarKind != "" && p.width > sidebarWidth {
		p.drawSidebar(bodyRows)
		contentX = sidebarWidth
	}

	lineNumArea := 0
	if d.General.LineNumMode {
		lineNumArea = lineNumWidth(d) + 1
	}
	textX := contentX + lineNumArea
	textW := p.width - textX
	if textW < 1 {
		textW = 1
	}

	y := 0
	// Ruler
	if d.General.Ruler > 0 && bodyRows > 0 {
		p.drawRuler(d, textX, textW, contentX)
		y += 2
	}

	// Header segments
	headerSegList := []Seg{}
	if d.headerSegs > 0 && d.headerSegs <= len(d.segs) {
		headerSegList = d.segs[:d.headerSegs]
	}
	for _, seg := range headerSegList {
		if y >= bodyRows {
			break
		}
		p.drawSegRow(d, seg, y, textX, textW, lineNumArea, true, false)
		y++
	}

	// Section header segments
	secLines := p.sectionHeaderLines(d)
	for _, li := range secLines {
		// draw all segments for this logical line
		for _, seg := range d.segs {
			if seg.LineIdx != li {
				continue
			}
			if y >= bodyRows {
				break
			}
			p.drawSegRow(d, seg, y, textX, textW, lineNumArea, true, true)
			y++
		}
		if y >= bodyRows {
			break
		}
	}

	// current section for hide-other
	var curSecStart, nextSecStart int
	hideOther := d.General.HideOtherSection && p.sectionRegexp(d) != nil
	if hideOther {
		topLine := d.segLine(d.TopSeg)
		curSecStart = p.sectionStartLineFor(d, topLine)
		nextSecStart = -1
		for _, s := range p.sectionStarts(d) {
			if s > curSecStart {
				nextSecStart = s
				break
			}
		}
		if curSecStart < 0 {
			curSecStart = d.skipCount()
			// next is first section
			if starts := p.sectionStarts(d); len(starts) > 0 {
				nextSecStart = starts[0]
			}
		}
	}

	jumpRow := -1
	if d.General.JumpTarget != "" {
		jumpRow = p.jumpOffsetSegs(d, d.segLine(d.TopSeg))
	}

	bodyRowIdx := 0
	for y < bodyRows {
		segIdx := d.TopSeg + bodyRowIdx
		isJumpRow := jumpRow >= 0 && bodyRowIdx == jumpRow
		if segIdx < 0 || segIdx >= len(d.segs) {
			// EOF / before-start row: tilde
			if !(hideOther && segIdx >= len(d.segs)) {
