			y++
			bodyRowIdx++
			continue
		}
		seg := d.segs[segIdx]
		if hideOther {
			if seg.LineIdx < curSecStart || (nextSecStart >= 0 && seg.LineIdx >= nextSecStart) {
				y++
				bodyRowIdx++
				continue
			}
		}
		p.drawSegRowEx(d, seg, y, textX, textW, lineNumArea, false, isJumpRow)
		y++
