	}
	if cursorY < 0 {
		cursorY = 0
	}
	if p.width > 0 && p.height > 0 {
		// cursor style
		ct := d.General.PromptNormalCursorType
		if p.input != nil {
			ct = d.General.PromptInputCursorType
		}
		p.screen.SetCursorStyle(tcell.CursorStyle(ct))
		p.screen.ShowCursor(cursorX, cursorY)
	}
