cat > draw.go << 'EOF'
package main

import (
	"fmt"
	"strings"

	"github.com/gdamore/tcell/v2"
)

const sidebarWidth = 16

func (p *Pager) drawText(x, y int, s string, style tcell.Style) {
	if y < 0 || y >= p.height {
		return
	}
	cx := x
	for _, r := range s {
		if cx >= p.width {
			break
		}
		if cx >= 0 {
			p.screen.SetContent(cx, y, r, nil, style)
		}
		cx++
	}
}

func (p *Pager) draw() {
	if p.screen == nil {
		return
	}
	p.width, p.height = p.screen.Size()
	p.screen.Clear()
	d := p.curDoc()
	if d == nil {
		p.screen.Show()
		return
	}
	d.mu.RLock()
	// ensure segments for this width
	contentW := p.contentWidthFor(d)
	d.ensureSegments(contentW)
	d.mu.RUnlock()

	statusEnabled := p.statusLine && p.height > 1
	bodyRows := p.height
	if statusEnabled {
		bodyRows = p.height - 1
	}
	if bodyRows < 0 {
		bodyRows = 0
	}

	// sidebar
	contentX := 0
	if p.sidebarKind != "" && p.width > sidebarWidth {
		p.drawSidebar(bodyRows)
		contentX = sidebarWidth
	}

	lineNumArea := 0
	if d.General.LineNumMode {
		lineNumArea = lineNumWidth(d) + 1
	}
	textX := contentX + lineNumArea
	textW := p.width - textX
	if textW < 1 {
		textW = 1
	}

	y := 0
	// Ruler
	if d.General.Ruler > 0 && bodyRows > 0 {
		p.drawRuler(d, textX, textW, contentX)
		y += 2
	}

	// Header segments
	headerSegList := []Seg{}
	if d.headerSegs > 0 && d.headerSegs <= len(d.segs) {
		headerSegList = d.segs[:d.headerSegs]
	}
	for _, seg := range headerSegList {
		if y >= bodyRows {
			break
		}
		p.drawSegRow(d, seg, y, textX, textW, lineNumArea, true, false)
		y++
	}

	// Section header segments
	secLines := p.sectionHeaderLines(d)
	for _, li := range secLines {
		// draw all segments for this logical line
		for _, seg := range d.segs {
			if seg.LineIdx != li {
				continue
			}
			if y >= bodyRows {
				break
			}
			p.drawSegRow(d, seg, y, textX, textW, lineNumArea, true, true)
			y++
		}
		if y >= bodyRows {
			break
		}
	}

	// current section for hide-other
	var curSecStart, nextSecStart int
	hideOther := d.General.HideOtherSection && p.sectionRegexp(d) != nil
	if hideOther {
		topLine := d.segLine(d.TopSeg)
		curSecStart = p.sectionStartLineFor(d, topLine)
		nextSecStart = -1
		for _, s := range p.sectionStarts(d) {
			if s > curSecStart {
				nextSecStart = s
				break
			}
		}
		if curSecStart < 0 {
			curSecStart = d.skipCount()
			// next is first section
			if starts := p.sectionStarts(d); len(starts) > 0 {
				nextSecStart = starts[0]
			}
		}
	}

	jumpRow := -1
	if d.General.JumpTarget != "" {
		jumpRow = p.jumpOffsetSegs(d, d.segLine(d.TopSeg))
	}

	bodyRowIdx := 0
	for y < bodyRows {
		segIdx := d.TopSeg + bodyRowIdx
		isJumpRow := jumpRow >= 0 && bodyRowIdx == jumpRow
		if segIdx < 0 || segIdx >= len(d.segs) {
			// EOF / before-start row: tilde
			if !(hideOther && segIdx >= len(d.segs)) {
				style := tcell.StyleDefault.Foreground(tcell.GetColor("gray"))
				// line number blank area already blank
				if textX < p.width {
					p.screen.SetContent(textX, y, '~', nil, style)
				}
			}
			y++
			bodyRowIdx++
			continue
		}
		seg := d.segs[segIdx]
		if hideOther {
			if seg.LineIdx < curSecStart || (nextSecStart >= 0 && seg.LineIdx >= nextSecStart) {
				y++
				bodyRowIdx++
				continue
			}
		}
		p.drawSegRowEx(d, seg, y, textX, textW, lineNumArea, false, isJumpRow)
		y++
		bodyRowIdx++
	}

	// status / input line
	cursorX, cursorY := p.width-1, p.height-1
	if statusEnabled || p.input != nil {
		cx := p.drawStatus(d)
		cursorX, cursorY = cx, p.height-1
	}
	if cursorX < 0 {
		cursorX = 0
	}
	if cursorX >= p.width {
		cursorX = p.width - 1
	}
	if cursorY < 0 {
		cursorY = 0
	}
	if p.width > 0 && p.height > 0 {
		// cursor style
		ct := d.General.PromptNormalCursorType
		if p.input != nil {
			ct = d.General.PromptInputCursorType
		}
		p.screen.SetCursorStyle(tcell.CursorStyle(ct))
		p.screen.ShowCursor(cursorX, cursorY)
	}
	p.screen.Show()
}

func (p *Pager) drawRuler(d *Document, textX, textW, contentX int) {
	style := d.General.Style.Ruler.applyTo(tcell.StyleDefault)
	margin := 0
	if d.General.LineNumMode {
		margin = lineNumWidth(d) + 1
	}
	for row := 0; row < 2; row++ {
		for x := contentX; x < p.width; x++ {
			var v int // 1-based virtual column
			if d.General.Ruler == 2 {
				v = x - contentX + 1
			} else {
				// relative: content column (after margin), shifted by scroll
				v = (x - contentX - margin) + d.X + 1
			}
			var ch rune
			if row == 0 {
				if v > 0 && v%10 == 0 {
					ch = rune('0' + (v/10)%10)
				} else {
					ch = ' '
				}
			} else {
				if v <= 0 {
					ch = '0'
				} else {
					ch = rune('0' + v%10)
				}
			}
			p.screen.SetContent(x, row, ch, nil, style)
		}
	}
}

func (p *Pager) segEndCell(d *Document, seg Seg) int {
	// next seg of same line determines end (in segment list order).
	// Find seg index by scanning for identity is expensive; instead compute
	// from segStartByLine in caller when possible. Here scan.
	cells := d.lineCells(seg.LineIdx)
	// find this seg's index
	idx := -1
	if d.segStartByLine != nil && seg.LineIdx < len(d.segStartByLine) {
		base := d.segStartByLine[seg.LineIdx]
		if base >= 0 {
			idx = base + seg.SegNo
		}
	}
	if idx >= 0 && idx+1 < len(d.segs) && d.segs[idx+1].LineIdx == seg.LineIdx {
		return d.segs[idx+1].StartCell
	}
	return len(cells)
}

func (p *Pager) drawSegRow(d *Document, seg Seg, y, textX, textW, lineNumArea int, isHeader bool, isSecHeader bool) {
	p.drawSegRowEx2(d, seg, y, textX, textW, lineNumArea, isHeader, isSecHeader, false)
}
func (p *Pager) drawSegRowEx(d *Document, seg Seg, y, textX, textW, lineNumArea int, isHeader bool, isJump bool) {
	p.drawSegRowEx2(d, seg, y, textX, textW, lineNumArea, isHeader, false, isJump)
}

func (p *Pager) drawSegRowEx2(d *Document, seg Seg, y, textX, textW, lineNumArea int, isHeader bool, isSecHeader bool, isJump bool) {
	contentX := textX - lineNumArea
	// line number / blank header number area
	if d.General.LineNumMode {
		numStyle := d.General.Style.LineNumber.applyTo(tcell.StyleDefault)
		if isHeader {
			// blank
			for x := contentX; x < textX && x < p.width; x++ {
				p.screen.SetContent(x, y, ' ', nil, tcell.StyleDefault)
			}
		} else {
			rel := seg.LineIdx - d.skipCount() - d.General.Header + 1
			if d.General.Header < 0 {
				rel = seg.LineIdx - d.skipCount() + 1
			}
			numW := lineNumWidth(d)
			s := fmt.Sprintf("%*d ", numW, rel)
			cx := contentX
			for _, r := range s {
				if cx < p.width {
					p.screen.SetContent(cx, y, r, nil, numStyle)
				}
				cx++
			}
		}
	}

	cells := d.lineCells(seg.LineIdx)
	endCell := p.segEndCell(d, seg)
	// Cells in this segment with their visual X in the full line.
	xs, _ := cellXs(cells)

	type placed struct {
		cell Cell
		x    int // visual x in full line
	}
	var seq []placed
	if d.General.WrapMode {
		for ci := seg.StartCell; ci < endCell && ci < len(cells); ci++ {
			seq = append(seq, placed{cells[ci], xs[ci]})
		}
	} else {
		// prefix (vertical header / header column)
		prefixEndX := 0     // visual x end of prefix
		prefixEndCell := 0  // cell index end of prefix
		if d.General.VerticalHeader > 0 {
			prefixEndX = d.General.VerticalHeader
			for ci, c := range cells {
				if xs[ci] < d.General.VerticalHeader {
					prefixEndCell = ci + 1
					_ = c
				}
			}
		}
		if d.General.HeaderColumn > 0 {
			fields := d.fieldsForLine(seg.LineIdx)
			hc := d.General.HeaderColumn
			if len(fields) >= hc {
				hf := fields[hc-1]
				endPlain := hf.DelimEnd
				if endPlain < 0 {
					endPlain = hf.End
				}
				// cells with PlainIdx < endPlain are prefix
				pe := 0
				pex := 0
				for ci, c := range cells {
					if c.PlainIdx < endPlain {
						pe = ci + 1
						pex = xs[ci] + c.Width
					}
				}
				if pex > prefixEndX {
					prefixEndX = pex
					prefixEndCell = pe
				}
			}
		}
		// prefix cells
		for ci := 0; ci < prefixEndCell && ci < len(cells); ci++ {
			seq = append(seq, placed{cells[ci], xs[ci]})
		}
		startX := prefixEndX + d.X
		for ci, c := range cells {
			if ci < prefixEndCell {
				continue
			}
			if xs[ci]+c.Width <= startX {
				continue
			}
			// partially cut wide char at left edge: represent with a leading space
			seq = append(seq, placed{c, xs[ci]})
		}
		_ = endCell
	}

	// shrink column (align mode): replace selected column cells with shrink char at first position
	// (applied as a style/rune substitution during placement below)

	// Precompute search / multicolor matches for this line.
	type matchRange struct {
		start, end int
		styleIdx   int // -1 = search highlight, >=0 multicolor index
	}
	var matches []matchRange
	pat := d.Pattern
	if p.input != nil && (p.input.Kind == InputSearch || p.input.Kind == InputBackSearch) {
		pat = string(p.input.Value)
	}
	if pat != "" {
		s := newSearcher(pat, p.regexpSearch, p.caseSensitive, p.smartCase)
		for _, m := range s.findMatches(d.parsed[seg.LineIdx].Plain) {
			matches = append(matches, matchRange{m[0], m[1], -1})
		}
	}
	for mi, mp := range d.MultiColors {
		if mp == "" {
			continue
		}
		s := &Searcher{Pattern: mp, Regexp: true, valid: true}
		s = newSearcher(mp, true, p.caseSensitive, false)
		for _, m := range s.findMatches(d.parsed[seg.LineIdx].Plain) {
			matches = append(matches, matchRange{m[0], m[1], mi})
		}
	}

	fields := d.fieldsForLine(seg.LineIdx)
	columnActive := d.General.ColumnMode || d.General.ColumnWidth

	isMarked := p.isMarked(d, seg.LineIdx)
	isSection := p.isSectionLine(d, seg.LineIdx)

	// Draw sequence.
	drawX := textX
	prefixVisual := 0
	_ = prefixVisual
	// In nowrap mode seq contains prefix + scrolled cells; their screen
	// positions are sequential from textX, except a wide char cut at the
	// left edge contributes a space first.
	firstBody := true
	for _, pl := range seq {
		c := pl.cell
		if !d.General.WrapMode && d.X > 0 && firstBody {
			// handled naturally: cells already filtered by startX; wide char partial
			// becomes a space if its start is before the visible start.
			prefixEndX := 0
			if d.General.VerticalHeader > 0 {
				prefixEndX = d.General.VerticalHeader
			}
			startX := prefixEndX + d.X
			// Determine whether this cell is a prefix cell by its x.
			isPrefixCell := prefixEndX > 0 && pl.x < prefixEndX
			if !isPrefixCell && pl.x < startX && c.Width > 1 {
				if drawX < p.width {
					p.screen.SetContent(drawX, y, ' ', nil, c.Style)
				}
				drawX++
			}
		}
		firstBody = false

		style := c.Style
		if isHeader {
			style = d.General.Style.Header.applyTo(style)
		}
		if isSecHeader {
			// section header lines keep any section-line styling below
		}
		if d.General.AlternateRows && !isHeader && (seg.LineIdx%2 == 1) {
			style = d.General.Style.Alternate.applyTo(style)
		}
		if isSection {
			style = d.General.Style.SectionLine.applyTo(style)
		}
		if isMarked {
			style = d.General.Style.MarkLine.applyTo(style)
		}
		// vertical header styling
		if d.General.VerticalHeader > 0 {
			if pl.x < d.General.VerticalHeader {
				style = d.General.Style.VerticalHeader.applyTo(style)
			}
			if pl.x == d.General.VerticalHeader-1 {
				style = d.General.Style.VerticalHeaderBorder.applyTo(style)
			}
		}
		// header column border: delimiter cell after last fixed field
		if d.General.HeaderColumn > 0 && fields != nil && len(fields) >= d.General.HeaderColumn {
			hf := fields[d.General.HeaderColumn-1]
			if hf.DelimStart >= 0 && c.PlainIdx >= hf.DelimStart && c.PlainIdx < hf.DelimEnd {
				style = d.General.Style.VerticalHeaderBorder.applyTo(style)
			}
		}
		// column highlight / rainbow
		if columnActive && fields != nil {
			fi := fieldIndexOf(fields, c.PlainIdx)
			if fi >= 0 {
				if d.General.ColumnRainbow {
					stys := d.General.Style.ColumnRainbow
					if len(stys) > 0 {
						style = stys[fi%len(stys)].applyTo(style)
					}
				} else if fi == d.ColumnCursor {
					style = d.General.Style.ColumnHighlight.applyTo(style)
				}
				// shrink: replace the selected column's first cell with shrink char
				_ = fi
			}
		}
		// multicolor + search (search last so it wins for reverse)
		for _, m := range matches {
			if c.PlainIdx >= m.start && c.PlainIdx < m.end {
				if m.styleIdx >= 0 {
					stys := d.General.Style.MultiColorHighlight
					if len(stys) > 0 {
						style = stys[m.styleIdx%len(stys)].applyTo(style)
					}
				}
			}
		}
		for _, m := range matches {
			if m.styleIdx == -1 && c.PlainIdx >= m.start && c.PlainIdx < m.end {
				style = d.General.Style.SearchHighlight.applyTo(style)
			}
		}
		if isJump {
			style = d.General.Style.JumpTargetLine.applyTo(style)
		}

		r := c.R
		// shrink column
		if d.General.ShrinkColumn && d.General.Converter == "align" && fields != nil {
			fi := fieldIndexOf(fields, c.PlainIdx)
			if fi == d.ColumnCursor {
				// only the first plain position of the field shows the shrink char; others become spaces?
				f := fields[fi]
				if c.PlainIdx == f.Start {
					r = firstRune(cfg.ShrinkChar, '…')
				} else {
					continue
				}
			}
		}

		if drawX >= textX+textW || drawX >= p.width {
			break
		}
		if c.Width == 2 && drawX+1 >= textX+textW {
			// wide char at right edge: leave blank
			p.screen.SetContent(drawX, y, ' ', nil, style)
			drawX++
			continue
		}
		p.screen.SetContent(drawX, y, r, c.Comb, style)
		drawX += c.Width
	}
}

func fieldIndexOf(fields []Field, plainIdx int) int {
	for i, f := range fields {
		if plainIdx >= f.Start && plainIdx < f.End {
			return i
		}
	}
	return -1
}

func (p *Pager) isMarked(d *Document, lineIdx int) bool {
	for _, m := range p.marks {
		if m.Doc == d && m.Line == lineIdx {
			return true
		}
	}
	return false
}

// drawStatus draws the status/input line and returns the cursor X.
func (p *Pager) drawStatus(d *Document) int {
	y := p.height - 1
	w := p.width
	// right part
	total := len(d.Lines)
	cur := p.currentLineNum(d)
	right := fmt.Sprintf("(%d/%d)", cur, total)
	if !d.EOF {
		right = fmt.Sprintf("(%d/%d...)", cur, total)
	}

	var left string
	leftReverseLen := 0
	cursorX := 0
	if p.input != nil {
		left = p.inputPromptText(d)
		cursorX = len([]rune(p.input.Prompt)) + len([]rune(p.input.Prefix())) + p.input.Cursor
		// Prompt already includes prefix+prompt+value in inputPromptText; recompute cursor:
		cursorX = p.inputCursorX(d)
		// draw left plain
		p.drawText(0, y, left, tcell.StyleDefault)
	} else {
		namePart := p.statusName(d) + ":"
		left = namePart + d.Message
		leftReverseLen = len([]rune(namePart))
		// draw name reversed, rest default
		style := tcell.StyleDefault
		if d.General.PromptInvertColor {
			style = style.Reverse(true)
		}
		runes := []rune(left)
		for i, r := range runes {
			if i >= w {
				break
			}
			st := tcell.StyleDefault
			if i < leftReverseLen {
				st = style
			}
			p.screen.SetContent(i, y, r, nil, st)
		}
		cursorX = leftReverseLen
	}
	// right overlay
	rx := w - len([]rune(right))
	if rx > 0 {
		p.drawText(rx, y, right, tcell.StyleDefault)
	}
	_ = left
	return cursorX
}

func (p *Pager) statusName(d *Document) string {
	name := d.displayName()
	// mode prefixes go before the name but after the index
	var modePrefix string
	if d.FollowSection {
		modePrefix = "(Follow Section)"
	} else if p.followAll {
		modePrefix = "(Follow All)"
	} else if d.Follow {
		modePrefix = "(Follow Mode)"
	} else if p.watchMode {
		modePrefix = "(Watch)"
	}
	if d.IsLog {
		// Log is always in follow mode.
		modePrefix = "(Follow Mode)"
	}
	var idxPrefix string
	if p.special == nil && len(p.docs) > 1 {
		idxPrefix = fmt.Sprintf("[%d]", indexOfDoc(p.docs, d))
	}
	return idxPrefix + modePrefix + name
}

func (p *Pager) drawSidebar(bodyRows int) {
	if bodyRows <= 0 {
		return
	}
	var title string
	switch p.sidebarKind {
	case "help":
		title = "Help"
	case "marks":
		title = "Marks"
	case "files":
		title = "Files"
	}
	p.drawText(0, 0, "   "+title, tcell.StyleDefault)
	lines := p.sidebarLines()
	for row := 1; row < bodyRows; row++ {
		idx := row - 1 + p.sidebarTop
		if idx < 0 || idx >= len(lines) {
			continue
		}
		txt := lines[idx]
		if p.sidebarX > 0 {
			r := []rune(txt)
			if p.sidebarX < len(r) {
				txt = string(r[p.sidebarX:])
			} else {
				txt = ""
			}
		}
		r := []rune(txt)
		if len(r) > sidebarWidth {
			r = r[:sidebarWidth]
		}
		p.drawText(0, row, string(r), tcell.StyleDefault)
	}
}

func (p *Pager) sidebarLines() []string {
	switch p.sidebarKind {
	case "help":
		return sidebarHelpLines()
	case "marks":
		var out []string
		for i, m := range p.marks {
			out = append(out, fmt.Sprintf("%2d %d %d", i, m.Line, m.Line+1))
			_ = m
		}
		return out
	case "files":
		var out []string
		for i, d := range p.docs {
			out = append(out, fmt.Sprintf(" %d %s", i, d.displayName()))
		}
		return out
	}
	return nil
}

