		}
	case tcell.KeyRight:
		if in.Cursor < len(in.Value) {
			in.Cursor++
		}
	case tcell.KeyRune:
		in.insertRune(ev.Rune())
		p.afterInputChange()
	default:
		// Ctrl+letter editing fallbacks
		if ev.Key() == tcell.KeyCtrlU {
			in.Value = nil
			in.Cursor = 0
			p.afterInputChange()
		}
	}
