		// (like confirming), without a "not found" message.
		if (in.Kind == InputSearch || in.Kind == InputBackSearch) && p.incsearch && d != nil {
			pat := string(in.Value)
			p.searchPattern = pat
			d.Pattern = pat
			p.addHistory(in.HistoryKey, pat)
		}
		p.closeInput()
	case tcell.KeyBackspace, tcell.KeyBackspace2:
		in.backspace()
		p.afterInputChange()
	case tcell.KeyDelete:
		in.deleteAt()
		p.afterInputChange()
	case tcell.KeyLeft:
		if in.Cursor > 0 {
			in.Cursor--
		}
	case tcell.KeyRight:
		if in.Cursor < len(in.Value) {
			in.Cursor++
		}
	case tcell.KeyRune:
		in.insertRune(ev.Rune())
		p.afterInputChange()
	default:
		// Ctrl+letter editing fallbacks
		if ev.Key() == tcell.KeyCtrlU {
			in.Value = nil
			in.Cursor = 0
			p.afterInputChange()
		}
	}
}

func (p *Pager) afterInputChange() {
	in := p.input
	if in == nil {
		return
	}
	if (in.Kind == InputSearch || in.Kind == InputBackSearch) && p.incsearch {
		p.incrementalSearch()
	}
}

func (p *Pager) incrementalSearch() {
	in := p.input
	d := p.curDoc()
	if d == nil {
		return
	}
	pat := string(in.Value)
	d.Pattern = pat
	p.searchPattern = pat
	if pat == "" {
		d.TopSeg = in.StartTopSeg
		return
	}
	s := newSearcher(pat, p.regexpSearch, p.caseSensitive, p.smartCase)
	forward := in.Kind == InputSearch
	found := d.findLine(s, in.StartLine, forward, true)
	if found < 0 {
		d.TopSeg = in.StartTopSeg
		return
	}
	p.moveToLine(d, found, true)
}

