func (in *InputState) PrefixFor(p *Pager) string {
	var b strings.Builder
	isSearch := in.Kind == InputSearch || in.Kind == InputBackSearch
	if in.NonMatch && in.Kind == InputFilter {
		b.WriteString("Non-match")
	}
	if p.regexpSearch {
		b.WriteString("(R)")
	}
	if isSearch && p.incsearch {
		b.WriteString("(I)")
	}
	if p.caseSensitive {
		b.WriteString("(Aa)")
	} else if p.smartCase {
		b.WriteString("(S)")
	}
	return b.String()
}

func (in *InputState) PromptFor(p *Pager) string {
	switch in.Kind {
	case InputSearch:
		return in.PrefixFor(p) + "/"
	case InputBackSearch:
		return in.PrefixFor(p) + "?"
	case InputFilter:
		return in.PrefixFor(p) + "&"
	case InputMarkPattern:
		return in.PrefixFor(p) + "*"
	default:
		return in.Label
	}
}

func displayWidthString(s string) int {
	return runewidth.StringWidth(s)
}

func (p *Pager) inputPromptText(d *Document) string {
	if p.input == nil {
		return ""
	}
	return p.input.PromptFor(p) + string(p.input.Value)
}

func (p *Pager) inputCursorX(d *Document) int {
	if p.input == nil {
		return 0
	}
	promptW := displayWidthString(p.input.PromptFor(p))
	before := string(p.input.Value[:p.input.Cursor])
	return promptW + displayWidthString(before)
}

func (p *Pager) openInput(kind InputKind, label string) {
	d := p.curDoc()
	in := &InputState{Kind: kind, Label: label}
	if d != nil {
		in.StartTopSeg = d.TopSeg
		in.StartLine = d.segLine(d.TopSeg)
	}
	switch kind {
	case InputSearch, InputBackSearch:
		in.HistoryKey = "search"
		in.Candidates = append([]string(nil), p.histories["search"]...)
	case InputFilter:
		in.HistoryKey = "filter"
		in.Candidates = append([]string(nil), p.histories["filter"]...)
	case InputMarkPattern:
		in.HistoryKey = "markpattern"
		in.Candidates = append([]string(nil), p.histories["markpattern"]...)
	case InputGoto:
		in.HistoryKey = "goto"
		in.Candidates = append([]string(nil), p.histories["goto"]...)
	case InputHeader, InputSkipLines, InputVerticalHeader, InputHeaderColumn, InputSectionHeaderNum:
		in.Numeric = true
	case InputTabWidth:
		in.Candidates = []string{"3", "2", "4", "8"}
	case InputWatchInterval:
		in.Candidates = []string{"3", "2", "1"}
	case InputSectionStart:
		in.Candidates = []string{"2", "1", "0"}
	case InputJumpTarget:
		in.Candidates = []string{"section"}
	case InputDelimiter:
		in.Candidates = []string{"│", "", "|", "/\\s+/", ","}
	case InputSectionDelimiter:
		in.Candidates = []string{"^commit", "^diff", "^#", "^$", "^\\f"}
