func (in *InputState) setValue(s string) {
	in.Value = []rune(s)
	in.Cursor = len(in.Value)
}

func (in *InputState) insertRune(r rune) {
	in.Value = append(in.Value, 0)
	copy(in.Value[in.Cursor+1:], in.Value[in.Cursor:])
	in.Value[in.Cursor] = r
	in.Cursor++
}

func (in *InputState) backspace() {
	if in.Cursor > 0 {
		in.Value = append(in.Value[:in.Cursor-1], in.Value[in.Cursor:]...)
		in.Cursor--
	}
}
func (in *InputState) deleteAt() {
	if in.Cursor < len(in.Value) {
		in.Value = append(in.Value[:in.Cursor], in.Value[in.Cursor+1:]...)
	}
}

func (in *InputState) nextCandidate() { // Down
	if in.Numeric {
		n, err := strconv.Atoi(string(in.Value))
		if err != nil {
			n = 0
		} else {
			n--
			if n < 0 {
				n = 0
			}
		}
		in.setValue(strconv.Itoa(n))
		return
	}
	if len(in.Candidates) == 0 {
		in.setValue("")
		return
	}
	in.CandIdx = (in.CandIdx + 1) % len(in.Candidates)
	in.setValue(in.Candidates[in.CandIdx])
}

func (in *InputState) prevCandidate() { // Up
	if in.Numeric {
		n, err := strconv.Atoi(string(in.Value))
		if err != nil {
			n = -1
		}
		n++
		in.setValue(strconv.Itoa(n))
		return
	}
	if len(in.Candidates) == 0 {
		in.setValue("")
		return
	}
	in.CandIdx--
	if in.CandIdx < 0 {
		in.CandIdx = len(in.Candidates) - 1
	}
	in.setValue(in.Candidates[in.CandIdx])
}

func (p *Pager) addHistory(key, val string) {
	if key == "" || val == "" {
		return
	}
	h := p.histories[key]
	// append (duplicates kept, as cycling through history duplicated)
	h = append(h, val)
	p.histories[key] = h
}

// handleInputKey returns true if the event was consumed by input handling.
func (p *Pager) handleInputKey(ev *tcell.EventKey) {
	in := p.input
	d := p.curDoc()
	desc := descFromEvent(ev)
	if action, ok := p.inputMap[desc]; ok {
		switch action {
		case "input_casesensitive":
			p.caseSensitive = !p.caseSensitive
			if p.caseSensitive {
				p.smartCase = false
			}
			p.afterInputChange()
			return
		case "input_smart_casesensitive":
			p.smartCase = !p.smartCase
			if p.smartCase {
				p.caseSensitive = false
			}
			p.afterInputChange()
			return
		case "input_regexp_search":
			p.regexpSearch = !p.regexpSearch
			p.afterInputChange()
			return
		case "input_incsearch":
			p.incsearch = !p.incsearch
			p.afterInputChange()
			return
		case "input_non_match":
			if in.Kind == InputFilter {
				in.NonMatch = !in.NonMatch
				return
			}
			// fall through to inserting '!'
		case "input_previous":
			in.prevCandidate()
			p.afterInputChange()
			return
		case "input_next":
			in.nextCandidate()
			p.afterInputChange()
			return
		case "input_copy":
			p.screen.SetClipboard([]byte(string(in.Value)))
			return
		case "input_paste":
			p.screen.GetClipboard()
			return
		}
	}

	switch ev.Key() {
	case tcell.KeyEnter, tcell.KeyCR:
		p.submitInput()
	case tcell.KeyEsc:
		// For incremental search, escaping keeps the current pattern/position
		// (like confirming), without a "not found" message.
		if (in.Kind == InputSearch || in.Kind == InputBackSearch) && p.incsearch && d != nil {
			pat := string(in.Value)
			p.searchPattern = pat
			d.Pattern = pat
			p.addHistory(in.HistoryKey, pat)
		}
		p.closeInput()
	case tcell.KeyBackspace, tcell.KeyBackspace2:
		in.backspace()
		p.afterInputChange()
	case tcell.KeyDelete:
		in.deleteAt()
		p.afterInputChange()
	case tcell.KeyLeft:
		if in.Cursor > 0 {
			in.Cursor--
		}
	case tcell.KeyRight:
		if in.Cursor < len(in.Value) {
			in.Cursor++
		}
	case tcell.KeyRune:
		in.insertRune(ev.Rune())
		p.afterInputChange()
	default:
		// Ctrl+letter editing fallbacks
		if ev.Key() == tcell.KeyCtrlU {
			in.Value = nil
			in.Cursor = 0
			p.afterInputChange()
		}
	}
}

func (p *Pager) afterInputChange() {
	in := p.input
	if in == nil {
		return
	}
	if (in.Kind == InputSearch || in.Kind == InputBackSearch) && p.incsearch {
		p.incrementalSearch()
	}
}

func (p *Pager) incrementalSearch() {
	in := p.input
	d := p.curDoc()
	if d == nil {
		return
	}
	pat := string(in.Value)
	d.Pattern = pat
	p.searchPattern = pat
	if pat == "" {
