	firstSeg := d.TopSeg
	lastSeg := firstSeg + bodySegs - 1
	// Include header lines in the range for "original" output? The reference
	// writes the current screen, which includes header rows when present for
	// the screen form. For the original form use logical lines of the body
	// plus header lines at the top of the file if displayed.
	firstLine := d.segLine(firstSeg)
	lastLine := d.segLine(lastSeg)
	if p.writeOriginal {
		fl := firstLine - p.writeBefore
		if d.General.Header > 0 {
			// header lines are at the top of the file; include them when the
			// current range starts after them? The current screen includes
			// them, so prepend them.
		}
		ll := lastLine + p.writeAfter
		if fl < 0 {
			fl = 0
		}
		if ll >= len(d.Lines) {
			ll = len(d.Lines) - 1
		}
		var b strings.Builder
		if d.General.Header > 0 && fl > d.skipCount() {
			for i := d.skipCount(); i < d.skipCount()+d.General.Header && i < len(d.Lines); i++ {
				b.WriteString(d.Lines[i] + "\n")
			}
		}
		for i := fl; i <= ll && i < len(d.Lines); i++ {
			if i < 0 {
				continue
			}
			b.WriteString(d.Lines[i] + "\n")
		}
		return b.String()
	}
	// Screen form: original logical lines in the displayed range.
	// (Wrapped segments are joined back to logical lines; header lines included.)
	var b strings.Builder
	fl := firstLine - p.writeBefore
	ll := lastLine + p.writeAfter
	if d.General.Header > 0 {
		for i := d.skipCount(); i < d.skipCount()+d.General.Header && i < len(d.Lines); i++ {
			b.WriteString(plainLineText(d, i) + "\n")
		}
	}
	if fl < 0 {
		fl = 0
	}
	for i := fl; i <= ll && i < len(d.Lines); i++ {
		b.WriteString(plainLineText(d, i) + "\n")
	}
	return b.String()
}

func plainLineText(d *Document, i int) string {
	d.ensureParsed()
	if i < 0 || i >= len(d.parsed) {
		return ""
	}
	// Use the displayed cells reconstructing tabs as expanded spaces etc.
	cells := d.lineCells(i)
	var b strings.Builder
	for _, c := range cells {
		b.WriteRune(c.R)
	}
	// Trim trailing spaces introduced only by trailing alignment? Keep as-is,
	// but the reference does not add trailing spaces beyond content.
	return strings.TrimRight(b.String(), " ")
}

func (p *Pager) pageMove(d *Document, dir int) {
	delta := p.bodyRows() * dir
	p.moveTop(d, delta)
}

func (p *Pager) scrollLeft(d *Document) {
	if d.General.ColumnMode || d.General.ColumnWidth {
		p.moveColumn(d, -1)
		return
	}
	p.hscroll(d, -1)
}
func (p *Pager) scrollRight(d *Document) {
	if d.General.ColumnMode || d.General.ColumnWidth {
		p.moveColumn(d, 1)
		return
	}
	p.hscroll(d, 1)
}

func (p *Pager) hscroll(d *Document, delta int) {
	d.X += delta
	if d.X < 0 {
		d.X = 0
	}
}

func (p *Pager) hscrollWidthAmount(d *Document) int {
	s := d.General.HScrollWidth
	w := p.contentWidthFor(d)
	return parseHScroll(s, w)
}

func parseHScroll(s string, width int) int {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	if strings.HasSuffix(s, "%") {
		if v, err := strconv.ParseFloat(strings.TrimSuffix(s, "%"), 64); err == nil {
			return int(float64(width) * v / 100)
		}
		return 0
	}
	if strings.HasPrefix(s, ".") || strings.HasPrefix(s, "-.") {
		if v, err := strconv.ParseFloat(s, 64); err == nil {
			return int(float64(width) * v)
		}
		return 0
	}
	if n, err := strconv.Atoi(s); err == nil {
		return n
	}
	return 0
}

func (p *Pager) endRight(d *Document) {
	d.ensureParsed()
	maxW := 0
	for i := range d.parsed {
		w := cellsWidth(d.lineCells(i))
		if w > maxW {
			maxW = w
		}
	}
	x := maxW - p.contentWidthFor(d) + 2
	if x < 0 {
		x = 0
	}
	d.X = x
}

func (p *Pager) moveColumn(d *Document, delta int) {
	topLine := d.segLine(d.TopSeg)
	fields := d.fieldsForLine(topLine)
	if len(fields) == 0 {
		d.Message = "Cannot move column: column not found"
		return
	}
	next := d.ColumnCursor + delta
	if next >= len(fields) {
		if cfg.DisableColumnCycle || opts.DisableColumnCycle {
			d.Message = "Cannot move column: column not found"
			return
		}
		next = 0
	}
	if next < 0 {
		if cfg.DisableColumnCycle || opts.DisableColumnCycle {
			d.Message = "Cannot move column: column not found"
			return
		}
		next = len(fields) - 1
	}
	d.ColumnCursor = next
	// In nowrap mode, scroll so the selected field is visible.
	if !d.General.WrapMode {
		p.scrollToColumn(d, fields[next])
	}
}

func (p *Pager) scrollToColumn(d *Document, f Field) {
	// Compute visual X of field start on the top line; adjust d.X if needed.
	topLine := d.segLine(d.TopSeg)
	cells := d.lineCells(topLine)
	x := 0
	for _, c := range cells {
		if c.PlainIdx >= f.Start {
			break
		}
		x += c.Width
	}
	w := p.contentWidthFor(d)
	// prefix width
	prefix := 0
	if d.General.VerticalHeader > 0 {
		prefix = d.General.VerticalHeader
	}
	if d.General.HeaderColumn > 0 {
		// header fields width
		fields := d.fieldsForLine(topLine)
		hc := d.General.HeaderColumn
		if len(fields) >= hc {
			hf := fields[hc-1]
			px := 0
			for _, c := range cells {
				if hf.DelimEnd >= 0 && c.PlainIdx < hf.DelimEnd {
					px += c.Width
				}
			}
			if px > prefix {
				prefix = px
			}
		}
	}
	avail := w - prefix
	if avail < 1 {
		return
	}
	if x < prefix+d.X {
		newX := x - prefix
		if newX < 0 {
			newX = 0
		}
		d.X = newX
	} else if x >= prefix+d.X+avail {
		d.X = x - prefix - avail + 1
	}
}

func (p *Pager) toggleSidebar(kind, msg string) {
	d := p.curDoc()
	if p.sidebarKind == kind {
		p.sidebarKind = ""
		if d != nil {
			d.Message = "Sidebar hidden"
		}
	} else {
		// switching to a different sidebar kind from another shows it
		p.sidebarKind = kind
		p.sidebarTop = 0
		p.sidebarX = 0
		if d != nil {
			d.Message = msg
		}
	}
	// Segment widths change.
	for _, dd := range p.docs {
		dd.segs = nil
		dd.segWidth = -1
	}
}

func (p *Pager) switchDoc(delta int) {
	if p.special != nil {
		p.special = nil
		return
	}
	if len(p.docs) <= 1 {
		return
	}
	src := p.docs[p.cur]
	next := p.cur + delta
	if next < 0 || next >= len(p.docs) {
		return
	}
	dst := p.docs[next]
	// Filter <-> parent synchronisation.
	if src.Kind == KindFilter && src.Parent == dst {
		orig := src.origLine(src.segLine(src.TopSeg))
		dst.ensureSegments(p.contentWidthFor(dst))
		dst.TopSeg = dst.firstSegOfLine(orig)
	} else if dst.Kind == KindFilter && dst.Parent == src {
		curLine := src.segLine(src.TopSeg)
		best := 0
		for i, m := range dst.LineMap {
			if m <= curLine {
				best = i
			} else {
				break
			}
		}
		dst.ensureSegments(p.contentWidthFor(dst))
		dst.TopSeg = dst.firstSegOfLine(best)
	}
	p.cur = next
	if opts.SetTerminalTitle || cfg.SetTerminalTitle {
		p.screen.SetTitle(dst.displayName())
	}
}

func (p *Pager) closeCurrentDoc() {
	if p.special != nil {
		p.special = nil
		return
	}
	if len(p.docs) <= 1 {
		p.docs[0].Message = "only this document"
		return
	}
	closed := p.docs[p.cur]
	_ = closed
	p.docs = append(p.docs[:p.cur], p.docs[p.cur+1:]...)
	if p.cur >= len(p.docs) {
		p.cur = len(p.docs) - 1
	}
	nd := p.docs[p.cur]
	nd.Message = fmt.Sprintf("close [%d]%s", p.cur, nd.displayName())
}

func (p *Pager) closeAllFilters() {
	// Closes all filter documents; if current is a filter, go to its parent.
	var closedNames []string
	var keep []*Document
	curDoc := p.curDoc()
	for _, d := range p.docs {
		if d.Kind == KindFilter {
			closedNames = append(closedNames, d.Name)
		} else {
			keep = append(keep, d)
		}
	}
	if len(closedNames) == 0 {
		return
	}
	p.docs = keep
	if curDoc != nil && curDoc.Kind == KindFilter && curDoc.Parent != nil {
		p.cur = indexOfDoc(p.docs, curDoc.Parent)
	} else if curDoc != nil {
		idx := indexOfDoc(p.docs, curDoc)
		if idx >= 0 {
			p.cur = idx
		}
	}
	if p.cur < 0 {
		p.cur = 0
	}
	if len(p.docs) > 0 {
		// Reference message (for a single filter): "close filter:<pat>"
		p.docs[p.cur].Message = "close " + closedNames[len(closedNames)-1]
		p.docs[p.cur].TopSeg = p.docs[p.cur].headerSegs
	}
}

func (p *Pager) closeFile(d *Document) {
	if d.FileClosed || d.Kind == KindHelp || d.Kind == KindLog || (d.Kind == KindFile && d.Seekable && d.FilePath != "" && !strings.HasSuffix(d.FilePath, ".gz") && !isCompressedName(d)) {
		// Regular seekable files that haven't been extracted cannot be closed
		// in the reference if they are plain files; compressed ones can.
		// Simplify: plain regular files cannot be closed.
		if d.Kind == KindFile {
			d.Message = "cannot be closed"
			return
		}
	}
	if d.Kind == KindFile {
		d.FileClosed = true
		d.Message = fmt.Sprintf("close file %s", d.Name)
		return
	}
	d.FileClosed = true
	name := d.Name
	if d.Kind == KindExecOut {
		name = "STDOUT"
	} else if d.Kind == KindExecErr {
		name = "STDERR"
	} else if d.Kind == KindFilter {
		d.Message = "close file"
		return
	}
	d.Message = fmt.Sprintf("close file %s", name)
}

func isCompressedName(d *Document) bool {
	if len(d.RawOrig) >= 4 {
		// RawOrig holds decompressed bytes, so this can't detect. Use extension list.
	}
	name := strings.ToLower(d.Name)
	for _, suf := range []string{".gz", ".bz2", ".xz", ".zst", ".lz4"} {
		if strings.HasSuffix(name, suf) {
			return true
		}
	}
	return false
}

func (p *Pager) addMark(d *Document) {
	line := d.segLine(d.TopSeg)
	for _, m := range p.marks {
		if m.Doc == d && m.Line == line {
			d.Message = fmt.Sprintf("Marked to line %d", displayLineNum(d, line))
			return
		}
	}
	p.marks = append(p.marks, Mark{Doc: d, DocIdx: indexOfDoc(p.docs, d), Line: line})
	// keep marks sorted by doc then line? The reference lists in insertion order
	// for simple cases; sort by (doc,line) if multiple? Keep insertion order.
	d.Message = fmt.Sprintf("Marked to line %d", displayLineNum(d, line))
}

func (p *Pager) removeMark(d *Document) {
	line := d.segLine(d.TopSeg)
	for i, m := range p.marks {
		if m.Doc == d && m.Line == line {
			p.marks = append(p.marks[:i], p.marks[i+1:]...)
			d.Message = fmt.Sprintf("Remove the mark at line %d", displayLineNum(d, line))
			return
		}
	}
	d.Message = fmt.Sprintf("Not marked line %d", displayLineNum(d, line))
}

// displayLineNum converts a logical 0-based line index to the user-facing
// (relative) line number used in messages.
func displayLineNum(d *Document, line int) int {
	return line - d.skipCount() - headerLogicalCount(d) + 1
}
func headerLogicalCount(d *Document) int {
	if d.General.Header > 0 {
		return d.General.Header
	}
	return 0
}

func (p *Pager) moveMark(d *Document, dir int) {
	if len(p.marks) == 0 {
		return
	}
	curLine := d.segLine(d.TopSeg)
	var target *Mark
	if dir > 0 {
		for i := range p.marks {
			m := &p.marks[i]
			if m.Doc == d && m.Line > curLine {
				target = m
				break
			}
		}
		if target == nil {
			// wrap to first mark of this doc
			for i := range p.marks {
				if p.marks[i].Doc == d {
					target = &p.marks[i]
					break
				}
			}
		}
	} else {
		for i := len(p.marks) - 1; i >= 0; i-- {
			m := &p.marks[i]
			if m.Doc == d && m.Line < curLine {
				target = m
				break
			}
		}
		if target == nil {
			for i := len(p.marks) - 1; i >= 0; i-- {
				if p.marks[i].Doc == d {
					target = &p.marks[i]
					break
				}
			}
		}
	}
	if target == nil {
		return
	}
	p.moveToLine(d, target.Line, false)
	d.Message = fmt.Sprintf("Moved to line %d", displayLineNum(d, target.Line))
}

func (p *Pager) repeatSearch(d *Document, forward bool) {
	if p.searchPattern == "" && d.Pattern == "" {
		return
	}
	pat := p.searchPattern
	if pat == "" {
		pat = d.Pattern
	}
	d.Pattern = pat
	s := newSearcher(pat, p.regexpSearch, p.caseSensitive, p.smartCase)
	curLine := d.segLine(d.TopSeg)
	found := d.findLine(s, curLine, forward, false)
	if found < 0 {
		d.Message = fmt.Sprintf("search:not found:%s", pat)
		return
	}
	p.moveToLine(d, found, true)
}

func (p *Pager) moveSection(d *Document, dir int) {
	starts := p.sectionStarts(d)
	if len(starts) == 0 {
		// Without a delimiter, next/previous section behaves like paging.
		p.pageMove(d, dir)
		return
	}
	curLine := d.segLine(d.TopSeg)
	if dir > 0 {
		for _, s := range starts {
			if s > curLine {
				p.moveToSectionLine(d, s)
				return
			}
		}
		d.Message = "No more next sections"
		return
	}
	// previous: last start < curLine; if curLine is inside a section, use its start.
	best := -1
	for _, s := range starts {
		if s < curLine {
			best = s
		} else {
			break
		}
	}
	if best < 0 {
		d.Message = "No more previous sections"
		return
	}
	p.moveToSectionLine(d, best)
}

func (p *Pager) moveToSectionLine(d *Document, line int) {
	seg := d.firstSegOfLine(line)
	seg -= d.General.SectionStart
	if seg < d.headerSegs {
		seg = d.headerSegs
	}
	d.TopSeg = seg
}

func (p *Pager) lastSection(d *Document) {
	starts := p.sectionStarts(d)
	if len(starts) == 0 {
		return
	}
	p.moveToSectionLine(d, starts[len(starts)-1])
}

func (p *Pager) followToSection(d *Document) {
	starts := p.sectionStarts(d)
	if len(starts) == 0 {
		p.goBottom(d)
		return
	}
	p.moveToSectionLine(d, starts[len(starts)-1])
}

func (p *Pager) reloadDoc(d *Document, watch bool) {
	if d.Kind == KindFile && d.FilePath != "" {
		data, err := os.ReadFile(d.FilePath)
		msgName := d.Name
		if err == nil {
			if watch {
				// Watch reload appends the file contents as a new copy.
				appendWatchLines(d, data)
			} else {
				dec := maybeDecompress(data)
				lines, noNL := splitLines(dec)
				d.mu.Lock()
				d.Lines = lines
				d.NoFinalNL = noNL
				d.RawOrig = dec
				d.mu.Unlock()
				d.invalidate()
				d.ensureSegments(p.contentWidthFor(d))
			}
			if fi, err := os.Stat(d.FilePath); err == nil {
				d.lastModSize = fi.Size()
				d.lastModTimeUnixNano = fi.ModTime().UnixNano()
			}
		}
		d.Message = fmt.Sprintf("reload file %s", msgName)
		return
	}
	if d.Kind == KindExecOut || d.Kind == KindExecErr {
		// Re-run the command, appending new output in watch mode.
		outD, errD := p.execDocsFor(d)
		if watch {
			// start a fresh execution appending to the docs
			if outD != nil && errD != nil {
				_ = p.startExec(d.ExecArgs, outD, errD)
			}
		} else {
			if outD != nil {
				outD.mu.Lock()
				outD.Lines = nil
				outD.EOF = false
				outD.mu.Unlock()
				outD.invalidate()
			}
			if errD != nil {
				errD.mu.Lock()
				errD.Lines = nil
				errD.EOF = false
				errD.mu.Unlock()
				errD.invalidate()
			}
			if outD != nil && errD != nil {
				_ = p.startExec(d.ExecArgs, outD, errD)
			}
		}
		name := "STDOUT"
		if d.Kind == KindExecErr {
			name = "STDERR"
		}
		d.Message = fmt.Sprintf("reload file %s", name)
		// In watch mode move to the start of the newest output.
		if watch {
			d.ensureSegments(p.contentWidthFor(d))
			d.TopSeg = d.firstSegOfLine(d.WatchBaseLine)
		}
		return
	}
	// stdin / mem: reload clears content (stream already consumed).
	if d.Kind == KindStdin {
		d.mu.Lock()
		d.Lines = nil
		d.RawOrig = nil
		d.mu.Unlock()
		d.invalidate()
		d.TopSeg = 0
	}
	d.Message = fmt.Sprintf("reload file %s", d.Name)
}

func appendWatchLines(d *Document, data []byte) {
	dec := maybeDecompress(data)
	lines, _ := splitLines(dec)
	d.mu.Lock()
	d.WatchBaseLine = len(d.Lines)
	// The reference separates reloads with an extra blank line.
	if len(d.Lines) > 0 {
		d.Lines = append(d.Lines, "")
		d.WatchBaseLine = len(d.Lines)
	}
	d.Lines = append(d.Lines, lines...)
	d.mu.Unlock()
	d.invalidate()
	d.ensureSegments(80)
}

func (p *Pager) execDocsFor(d *Document) (outD, errD *Document) {
	for _, dd := range p.docs {
		if dd.ExecCmd != nil && dd.ExecArgs != nil {
			if dd.Kind == KindExecOut {
				outD = dd
			} else if dd.Kind == KindExecErr {
				errD = dd
			}
		}
	}
	// If there are multiple exec pairs this is approximate; prefer siblings adjacent to d.
	idx := indexOfDoc(p.docs, d)
	if d.Kind == KindExecOut {
		outD = d
		if idx+1 < len(p.docs) && p.docs[idx+1].Kind == KindExecErr {
			errD = p.docs[idx+1]
		}
	} else if d.Kind == KindExecErr {
		errD = d
		if idx-1 >= 0 && p.docs[idx-1].Kind == KindExecOut {
			outD = p.docs[idx-1]
		}
	}
	return
}

func (p *Pager) openHelp() {
	if p.helpDoc == nil {
		content := buildHelpDocContent()
		gen := cloneGeneral(p.curDoc().General)
		gen.Header = 2
		gen.LineNumMode = false
		gen.ColumnMode = false
		gen.ColumnWidth = false
		hd := &Document{Kind: KindHelp, Name: "Help", General: gen, EOF: true, IsHelp: true}
		lines, _ := splitLines([]byte(content))
		hd.Lines = lines
		hd.ensureParsed()
		p.helpDoc = hd
	}
	hd := p.helpDoc
	hd.ensureSegments(p.contentWidthFor(hd))
	hd.TopSeg = hd.headerSegs
	p.special = hd
}

func buildHelpDocContent() string {
	full := helpKeyString()
	lines := strings.Split(full, "\n")
	// Replace the first line with the help-screen title line.
	if len(lines) > 0 {
		lines[0] = strings.Repeat(" ", 24) + "ov help"
	}
	return strings.Join(lines, "\n")
}

func (p *Pager) openLog() {
	if p.logDoc == nil {
		gen := cloneGeneral(p.curDoc().General)
		gen.LineNumMode = false
		gen.ColumnMode = false
		gen.Header = 0
		ld := &Document{Kind: KindLog, Name: "Log", General: gen, EOF: false, IsLog: true, Follow: true}
		ld.Lines = append([]string(nil), p.logLines...)
		ld.ensureParsed()
		p.logDoc = ld
	} else {
		p.logDoc.Lines = append([]string(nil), p.logLines...)
		p.logDoc.invalidate()
	}
	ld := p.logDoc
	ld.ensureSegments(p.contentWidthFor(ld))
	p.goBottom(ld)
	p.special = ld
}

func (p *Pager) editCurrent(d *Document) {
	if d.FilePath == "" {
		// Still try with the display name (matches message shape?)
		// For stdin etc. the reference behaviour is unclear; do nothing.
		return
	}
	editor := os.Getenv("VISUAL")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		if path, err := exec.LookPath("sensible-editor"); err == nil {
			editor = path
		} else {
			editor = "vi"
		}
	}
	curLine := d.segLine(d.TopSeg)
	args := splitCommand(editor)
	args = append(args, d.FilePath)
	fullCmdStr := strings.Join(append(splitCommand(editor), d.FilePath), " ")
	_ = p.screen.Suspend()
	c := exec.Command(args[0], args[1:]...)
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err == nil {
		c.Stdin = tty
		c.Stdout = tty
		c.Stderr = tty
		defer tty.Close()
	} else {
		c.Stdin = os.Stdin
		c.Stdout = os.Stdout
		c.Stderr = os.Stderr
	}
	runErr := c.Run()
	_ = p.screen.Resume()
	if runErr != nil {
		d.Message = fmt.Sprintf("failed to run editor command '%s': %s", fullCmdStr, runErr.Error())
		return
	}
	// reload
	data, err := os.ReadFile(d.FilePath)
	if err == nil {
		dec := maybeDecompress(data)
		lines, noNL := splitLines(dec)
		d.mu.Lock()
		d.Lines = lines
		d.NoFinalNL = noNL
		d.RawOrig = dec
		d.mu.Unlock()
		d.invalidate()
		d.ensureSegments(p.contentWidthFor(d))
	}
	p.moveToLine(d, curLine, false)
	d.Message = fmt.Sprintf("Moved to line %d", displayLineNum(d, curLine))
}

// splitCommand splits a command string on whitespace, handling simple quotes.
func splitCommand(s string) []string {
	var out []string
	var cur strings.Builder
	inS, inD := false, false
	for _, r := range s {
		switch {
		case r == '\'' && !inD:
			inS = !inS
		case r == '"' && !inS:
			inD = !inD
		case r == ' ' && !inS && !inD:
			if cur.Len() > 0 {
				out = append(out, cur.String())
				cur.Reset()
			}
		default:
			cur.WriteRune(r)
		}
	}
	if cur.Len() > 0 {
		out = append(out, cur.String())
	}
	return out
}

func (p *Pager) handleMouse(ev *tcell.EventMouse) {
	d := p.curDoc()
	if d == nil {
		return
	}
	d.Message = ""
	btn := ev.Buttons()
	if btn&tcell.WheelDown != 0 {
		n := d.General.VScrollLines
		if n <= 0 {
			n = 2
		}
		p.moveTop(d, n)
	} else if btn&tcell.WheelUp != 0 {
		n := d.General.VScrollLines
		if n <= 0 {
			n = 2
		}
		p.moveTop(d, -n)
	} else if btn&tcell.Button1 != 0 {
		x, y := ev.Position()
		_ = x
		// Clicking on the status line on the file name area? No-op placeholder.
		_ = y
	}
	_ = regexp.MustCompile
}

func (p *Pager) onTick() {
	now := time.Now()
	// Follow files: check for growth.
	for _, d := range p.docs {
		if d.Kind == KindFile && (d.Follow || p.followAll) && !d.FileClosed {
			if fi, err := os.Stat(d.FilePath); err == nil {
				if fi.Size() != d.lastModSize || fi.ModTime().UnixNano() != d.lastModTimeUnixNano {
					wasBottom := d.TopSeg >= p.endTopSeg(d)
					data, err := os.ReadFile(d.FilePath)
					if err == nil {
						dec := maybeDecompress(data)
						lines, noNL := splitLines(dec)
						d.mu.Lock()
						d.Lines = lines
						d.NoFinalNL = noNL
						d.RawOrig = dec
						d.mu.Unlock()
						d.invalidate()
						d.ensureSegments(p.contentWidthFor(d))
						if d.FollowSection {
							p.followToSection(d)
						} else if wasBottom || d.Follow {
							p.goBottom(d)
						}
					}
					d.lastModSize = fi.Size()
					d.lastModTimeUnixNano = fi.ModTime().UnixNano()
				}
			}
		}
		// Streaming docs: if follow, keep at bottom.
		if (d.Kind == KindStdin || d.Kind == KindExecOut || d.Kind == KindExecErr) && d.Follow {
			d.ensureSegments(p.contentWidthFor(d))
			p.goBottom(d)
		}
	}
	if p.watchMode && p.watchInterval > 0 {
		if now.Sub(p.lastWatch) >= time.Duration(p.watchInterval)*time.Second {
			p.lastWatch = now
			// reload the current doc (and exec siblings handled inside)
			if d := p.curDoc(); d != nil && p.special == nil {
				// For exec, only re-run once (from the stdout doc).
				target := d
				if d.Kind == KindExecErr {
					outD, _ := p.execDocsFor(d)
					if outD != nil {
						target = outD
					}
				}
				msg := target.Message
				p.reloadDoc(target, true)
				_ = msg
			}
		}
	}
	// EOF notifications for streaming docs that just finished.
	if opts.NotifyEOF > 0 {
		if d := p.curDoc(); d != nil && d.EOF && d.notifyCount < opts.NotifyEOF {
			// Only notify if not already shown at start (count tracks it).
			if d.Message == "" {
				d.Message = fmt.Sprintf("EOF reached: %s", d.Name)
			}
			d.notifyCount = opts.NotifyEOF
		}
	}
}

func (p *Pager) submitInput() {
	in := p.input
	if in == nil {
		return
	}
	d := p.curDoc()
	val := string(in.Value)
	kind := in.Kind
	histKey := in.HistoryKey
	nonMatch := in.NonMatch
	p.closeInput()
	if histKey != "" {
		p.addHistory(histKey, val)
	}
	if d == nil {
		return
	}
	d.Message = ""
	switch kind {
	case InputSearch, InputBackSearch:
		forward := kind == InputSearch
		p.searchPattern = val
		d.Pattern = val
		if val == "" {
			return
		}
		if p.incsearch {
			// Already positioned by incremental search; verify existence from start.
			s := newSearcher(val, p.regexpSearch, p.caseSensitive, p.smartCase)
			if d.findLine(s, in.StartLine, forward, true) < 0 {
				d.TopSeg = in.StartTopSeg
				d.Message = fmt.Sprintf("search:not found:%s", val)
			}
			return
		}
		s := newSearcher(val, p.regexpSearch, p.caseSensitive, p.smartCase)
		found := d.findLine(s, in.StartLine, forward, true)
		if found < 0 {
			d.Message = fmt.Sprintf("search:not found:%s", val)
			return
		}
		p.moveToLine(d, found, true)
	case InputFilter:
		if val == "" {
			return
		}
		fd := p.createFilter(d, val, nonMatch)
		p.insertDocAfter(d, fd)
		p.cur = indexOfDoc(p.docs, fd)
		p.searchPattern = val
	case InputGoto:
		if val == "" {
			return
		}
		p.doGoto(d, val)
	case InputMarkNumber:
		p.sidebarKind = ""
		if val == "" {
			d.Message = "Sidebar hidden"
			return
		}
		n, err := strconv.Atoi(val)
		if err != nil || n < 0 || n >= len(p.marks) {
			d.Message = "Sidebar hidden"
			return
		}
		m := p.marks[n]
		if idx := indexOfDoc(p.docs, m.Doc); idx >= 0 {
			p.cur = idx
		}
		md := p.curDoc()
		p.moveToLine(md, m.Line, false)
		md.Message = fmt.Sprintf("Moved to line %d", displayLineNum(md, m.Line))
	case InputMarkPattern:
		if val == "" {
			return
		}
		s := newSearcher(val, p.regexpSearch, p.caseSensitive, p.smartCase)
		d.ensureParsed()
		added := 0
		for i := range d.parsed {
			if len(s.findMatches(d.parsed[i].Plain)) > 0 {
				exists := false
				for _, m := range p.marks {
					if m.Doc == d && m.Line == i {
						exists = true
						break
					}
				}
				if !exists {
					p.marks = append(p.marks, Mark{Doc: d, DocIdx: indexOfDoc(p.docs, d), Line: i})
				}
				added++
			}
		}
		d.Message = fmt.Sprintf("Added %d marks", added)
	case InputHeader:
		n, err := strconv.Atoi(val)
		if val == "" {
			return
		}
		if err != nil {
			d.Message = "Set header lines: invalid number"
			return
		}
		d.General.Header = n
		d.Message = fmt.Sprintf("Set header lines %d", n)
		d.invalidate()
		d.ensureSegments(p.contentWidthFor(d))
		d.TopSeg = d.headerSegs
	case InputTabWidth:
		if val == "" {
			return
		}
		n, err := strconv.Atoi(val)
		if err != nil {
			d.Message = "invalid number"
			return
		}
		d.General.TabWidth = n
		d.Message = fmt.Sprintf("Set tab width %d", n)
		d.invalidate()
	case InputDelimiter:
		if val == "" {
			return
		}
		d.General.ColumnDelimiter = val
		d.Message = fmt.Sprintf("Set delimiter %s", val)
		d.ColumnCursor = initialColumnCursor(d)
	case InputMultiColor:
		if strings.TrimSpace(val) == "" {
			d.MultiColors = nil
			d.Message = "Set multicolor strings []"
			return
		}
		// MultiColor input is space-separated in candidates but comma in flags.
		// The reference message shows the parsed list like [1 2]? It showed [1,2]
		// for input "1,2". Split on commas and/or spaces? Flags use commas.
		parts := splitMultiColor(val)
		d.MultiColors = parts
		d.Message = fmt.Sprintf("Set multicolor strings [%s]", strings.Join(parts, ","))
	case InputJumpTarget:
		if val == "" {
			return
		}
		d.General.JumpTarget = val
		d.Message = fmt.Sprintf("Set JumpTarget %s", val)
	case InputViewMode:
		if val == "" {
			return
		}
		if !p.setDocMode(d, val) {
			d.Message = fmt.Sprintf("view mode not found: %s", val)
			return
		}
		d.Message = fmt.Sprintf("Set mode %s", val)
	case InputVerticalHeader:
		if val == "" {
			return
		}
		n, err := strconv.Atoi(val)
		if err != nil {
			d.Message = "invalid number"
			return
		}
		d.General.VerticalHeader = n
		d.Message = fmt.Sprintf("Set vertical header %d", n)
	case InputHeaderColumn:
		if val == "" {
			return
		}
		n, err := strconv.Atoi(val)
		if err != nil {
			d.Message = "invalid number"
			return
		}
		d.General.HeaderColumn = n
		d.Message = fmt.Sprintf("Set vertical header column %d", n)
		if n > 0 {
			d.ColumnCursor = n
		}
		d.segs = nil
	case InputSkipLines:
		if val == "" {
			return
		}
		n, err := strconv.Atoi(val)
		if err != nil {
			d.Message = "invalid number"
			return
		}
		d.General.SkipLines = n
		d.Message = fmt.Sprintf("Set skip lines %d", n)
		d.invalidate()
		d.ensureSegments(p.contentWidthFor(d))
		d.TopSeg = d.headerSegs
	case InputWatchInterval:
		if val == "" {
			return
		}
		n, err := strconv.Atoi(val)
		if err != nil {
			d.Message = "invalid number"
			return
		}
		p.watchInterval = n
		p.watchMode = true
		p.lastWatch = time.Now()
		d.Message = fmt.Sprintf("Set watch interval %d", n)
	case InputSectionDelimiter:
		if val == "" {
			return
		}
		d.General.SectionDelimiter = val
		d.Message = fmt.Sprintf("Set section delimiter %s", val)
	case InputSectionStart:
		if val == "" {
			return
		}
		n, err := strconv.Atoi(val)
		if err != nil {
			d.Message = "Set section start position: invalid number"
			return
		}
		d.General.SectionStart = n
		d.Message = fmt.Sprintf("Set section start position %d", n)
	case InputSectionHeaderNum:
		if val == "" {
			return
		}
		n, err := strconv.Atoi(val)
		if err != nil {
			d.Message = "invalid number"
			return
		}
		d.General.SectionHeaderNum = n
		d.Message = fmt.Sprintf("Set section header num %d", n)
	case InputConvert:
		if val == "" {
			return
		}
		d.General.Converter = val
		d.Message = fmt.Sprintf("Set %s converter", val)
		d.invalidate()
	case InputSaveFile:
		if val == "" {
			return
		}
		err := os.WriteFile(val, d.RawOrig, 0o644)
		if err != nil {
			d.Message = fmt.Sprintf("failed to save: %s", err.Error())
			return
		}
		d.Message = fmt.Sprintf("saved %s", val)
	case InputWriteAndQuit:
		before, after := parseBeforeAfter(val)
		p.doQuit(true, false, before, after)
	}
}

func parseBeforeAfter(s string) (int, int) {
	parts := strings.Split(s, ":")
	var b, a int
	if len(parts) >= 1 {
		b, _ = strconv.Atoi(strings.TrimSpace(parts[0]))
	}
	if len(parts) >= 2 {
		a, _ = strconv.Atoi(strings.TrimSpace(parts[1]))
	}
	return b, a
}

func splitMultiColor(val string) []string {
	// The dot-prompt candidates are space separated; flags are comma separated.
	// Reference message for input "1,2" was [1,2] (kept comma). For space
	// separated candidate strings, patterns are the words.
	if strings.Contains(val, ",") {
		parts := strings.Split(val, ",")
		var out []string
		for _, p := range parts {
			p = strings.TrimSpace(p)
			if p != "" {
				out = append(out, strings.Fields(p)...)
			}
		}
		// If the value had commas but no spaces inside fields, the above
		// already handles it. Return combined list.
		return out
	}
	return strings.Fields(val)
}

func (p *Pager) doGoto(d *Document, val string) {
	total := len(d.Lines)
	// relative line numbering: subtract skip+header
	offset := d.skipCount() + headerLogicalCount(d)
	relTotal := total - offset
	if strings.HasSuffix(val, "%") {
		num := strings.TrimSuffix(val, "%")
		f, err := strconv.ParseFloat(num, 64)
		if err != nil {
			d.Message = "invalid number"
			return
		}
		target := int(float64(relTotal) * f / 100.0)
		p.gotoRel(d, target, f == 100, val)
		return
	}
	if strings.HasPrefix(val, ".") {
		f, err := strconv.ParseFloat(val, 64)
		if err != nil {
			d.Message = "invalid number"
			return
		}
		target := int(float64(relTotal) * f)
		p.gotoRel(d, target, false, val)
		return
	}
	if strings.Contains(val, ".") {
		f, err := strconv.ParseFloat(val, 64)
		if err != nil {
			d.Message = "invalid number"
			return
		}
		target := int(f)
		p.gotoRel(d, target, false, val)
		return
	}
	n, err := strconv.Atoi(val)
	if err != nil {
		d.Message = "invalid number"
		return
	}
	p.gotoRelInt(d, n)
}

func (p *Pager) gotoRel(d *Document, relTarget int, isHundred bool, raw string) {
	offset := d.skipCount() + headerLogicalCount(d)
	total := len(d.Lines)
	relTotal := total - offset
	rel := relTarget
	if rel > relTotal {
		rel = relTotal
	}
	// Message formatting matches reference quirks.
	var msg string
	if isHundred {
		msg = fmt.Sprintf("Moved to line %d", rel)
	} else if strings.Contains(raw, ".") && !strings.HasSuffix(raw, "%") && rel == 0 && raw == ".0" {
		msg = "Moved to line 0"
	} else {
		msg = fmt.Sprintf("Moved to line %v", floatStr(float64(rel)))
	}
	// float line 0 cases:
	if rel == 0 && (raw == ".0") {
		msg = "Moved to line 0"
	}
	lineIdx := rel - 1 + offset
	if rel == 0 {
		lineIdx = -1 + offset
		// segment just before first line
		d.TopSeg = d.firstSegOfLine(0) - 1
		if offset > 0 {
			d.TopSeg = d.firstSegOfLine(lineIdx)
		}
		d.Message = msg
		return
	}
	if lineIdx >= total {
		lineIdx = total - 1
	}
	d.TopSeg = d.firstSegOfLine(lineIdx)
	d.Message = msg
}

func floatStr(f float64) string {
	// Reference prints e.g. 6172.0 for ratio moves.
	if f == float64(int64(f)) {
		return fmt.Sprintf("%d.0", int64(f))
	}
	return fmt.Sprintf("%v", f)
}

func (p *Pager) gotoRelInt(d *Document, rel int) {
	offset := d.skipCount() + headerLogicalCount(d)
	total := len(d.Lines)
	relTotal := total - offset
	disp := rel
	if rel > relTotal {
		disp = relTotal
	}
	if rel <= 0 {
		// line 0 or negative: show a tilde row before the first line.
		d.TopSeg = d.firstSegOfLine(0) + rel - 1
		if rel == 0 {
			d.TopSeg = d.firstSegOfLine(0) - 1
		}
		d.Message = fmt.Sprintf("Moved to line %d", rel)
		return
	}
	lineIdx := rel - 1 + offset
	if lineIdx >= total {
		lineIdx = total - 1
	}
	d.TopSeg = d.firstSegOfLine(lineIdx)
	d.Message = fmt.Sprintf("Moved to line %d", disp)
}
