package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/gdamore/tcell/v2"
	"github.com/gdamore/tcell/v2/terminfo"
)

func makeScreen() (tcell.Screen, error) {
	term := os.Getenv("TERM")
	name := term
	switch term {
	case "screen":
		if os.Getenv("TMUX") != "" {
			name = "tmux-256color"
		} else {
			name = "screen-256color"
		}
	case "tmux":
		name = "tmux-256color"
	case "", "dumb":
		if os.Getenv("TMUX") != "" {
			name = "tmux-256color"
		} else {
			name = "xterm-256color"
		}
	}
	ti, err := tcell.LookupTerminfo(name)
	if err != nil {
		// Unknown terminal: fall back to a 256-color xterm-like description.
		fallback := "xterm-256color"
		if os.Getenv("TMUX") != "" {
			fallback = "tmux-256color"
		}
		ti, err = tcell.LookupTerminfo(fallback)
		if err != nil {
			scr, err2 := tcell.NewScreen()
			if err2 != nil {
				return nil, fmt.Errorf("Screen.Init(): %w", err)
			}
			if err := scr.Init(); err != nil {
				return nil, fmt.Errorf("Screen.Init(): %w", err)
			}
			return scr, nil
		}
	}
	clone := *ti
	// Supplement capabilities the reference always emits.
	clone.XTermLike = true
	if clone.Italic == "" {
		clone.Italic = "\x1b[3m"
	}
	if clone.StrikeThrough == "" {
		clone.StrikeThrough = "\x1b[9m"
	}
	if clone.Colors >= 256 {
		clone.SetFg = "\x1b[%?%p1%{8}%<%t3%p1%d%e38;5;%p1%d%;m"
		clone.SetBg = "\x1b[%?%p1%{8}%<%t4%p1%d%e48;5;%p1%d%;m"
		clone.SetFgBg = ""
	}
	_ = strings.TrimSpace
	var tiPtr *terminfo.Terminfo = &clone
	scr, err := tcell.NewTerminfoScreenFromTtyTerminfo(nil, tiPtr)
	if err != nil {
		return nil, fmt.Errorf("Screen.Init(): %w", err)
	}
	if err := scr.Init(); err != nil {
		return nil, fmt.Errorf("Screen.Init(): %w", err)
	}
	return scr, nil
}
