old_start=t.index("func (d *Document) ensureParsed() {")
old_end=t.index("func delimRunes(s string) []rune {")
new_block=r'''func needsFullParse(ln string) bool {
	if !utf8.ValidString(ln) {
		return true
	}
	return strings.ContainsAny(ln, "\x1b\b")
}

func fastPlain(ln string) string {
	if strings.ContainsRune(ln, '\r') {
		return strings.ReplaceAll(ln, "\r", "")
	}
	return ln
}

func (d *Document) ensureParsed() {
	if d.parsed != nil {
		return
	}
	d.bodyStyle = d.bodyStyleNow()
	conv := d.General.Converter
	d.parsed = make([]ParsedLine, len(d.Lines))
	for i, ln := range d.Lines {
		if needsFullParse(ln) && !(conv == "raw" && !strings.ContainsRune(ln, '\b')) {
			d.parsed[i] = parseLine(ln, d.General.TabWidth, conv, d.General.Plain, d.bodyStyle, cfg.StyleOverStrike, cfg.StyleOverLine)
		} else {
			d.parsed[i] = ParsedLine{Plain: fastPlain(ln)}
		}
	}
	d.display = nil
	d.fields = nil
	if d.General.ColumnWidth {
		d.computeWidthCols()
	}
	if conv == "align" {
		d.buildAlign()
	}
}

func (d *Document) plainRunes(i int) []rune {
	if d.parsed[i].PlainRunes == nil {
		d.parsed[i].PlainRunes = []rune(d.parsed[i].Plain)
	}
	return d.parsed[i].PlainRunes
}

// displayCells returns cells for line i (aligned if applicable), parsing lazily.
func (d *Document) lineCells(i int) []Cell {
	if d.display != nil {
		return d.display[i]
	}
	if !d.parsed[i].CellsDone {
		pl := parseLine(d.Lines[i], d.General.TabWidth, d.General.Converter, d.General.Plain, d.bodyStyle, cfg.StyleOverStrike, cfg.StyleOverLine)
		// Keep the existing Plain string identity if it matches, to avoid churn.
		d.parsed[i] = pl
	}
	return d.parsed[i].Cells
}

// lineSegWidths simulates wrapping of a line by rune widths without building cells.
// It returns the start widths of each segment.
func (d *Document) lineSegWidths(i int, contentWidth int) []int {
	plain := d.parsed[i].Plain
	conv := d.General.Converter
	tabW := d.General.TabWidth
	starts := []int{0}
	x := 0
	cur := 0
	for _, r := range plain {
		var w int
		switch {
		case r == '\t':
			if tabW < 0 {
				w = 2
			} else if tabW == 0 {
				w = 0
			} else {
				w = tabW - (x % tabW)
			}
		case r == 0x1b && conv == "raw":
			w = 2
		case r < 0x20 || r == 0x7f:
			w = 1
		default:
			w = runewidth.RuneWidth(r)
		}
		if cur+w > contentWidth && cur > 0 {
			starts = append(starts, x)
			cur = 0
		}
		cur += w
		x += w
	}
	return starts
