// ansiForStyle renders a tcell style as an SGR sequence (reset + codes).
func ansiForStyle(style tcell.Style) string {
	fg, bg, attrs := style.Decompose()
	var codes []string
	addColor := func(c tcell.Color, isBg bool) {
		if !c.Valid() {
			return
		}
		if c.IsRGB() {
			r, g, b := c.RGB()
			if isBg {
				codes = append(codes, fmt.Sprintf("48;2;%d;%d;%d", r, g, b))
			} else {
				codes = append(codes, fmt.Sprintf("38;2;%d;%d;%d", r, g, b))
			}
			return
		}
		idx := int(c & 0xff)
		if isBg {
			if idx < 8 {
				codes = append(codes, fmt.Sprintf("%d", 40+idx))
			} else {
				codes = append(codes, fmt.Sprintf("48;5;%d", idx))
			}
		} else {
			if idx < 8 {
				codes = append(codes, fmt.Sprintf("%d", 30+idx))
			} else {
				codes = append(codes, fmt.Sprintf("38;5;%d", idx))
			}
		}
	}
	addColor(fg, false)
	addColor(bg, true)
	if attrs&tcell.AttrBold != 0 {
		codes = append(codes, "1")
	}
	if attrs&tcell.AttrDim != 0 {
		codes = append(codes, "2")
	}
	if attrs&tcell.AttrItalic != 0 {
		codes = append(codes, "3")
	}
	if us := style.GetUnderlineStyle(); us != tcell.UnderlineStyleNone {
		switch us {
		case tcell.UnderlineStyleSolid:
			codes = append(codes, "4")
		case tcell.UnderlineStyleDouble:
			codes = append(codes, "4:2")
		case tcell.UnderlineStyleCurly:
			codes = append(codes, "4:3")
		case tcell.UnderlineStyleDotted:
			codes = append(codes, "4:4")
		case tcell.UnderlineStyleDashed:
			codes = append(codes, "4:5")
		}
	} else if attrs&tcell.AttrUnderline != 0 {
		codes = append(codes, "4")
	}
	if attrs&tcell.AttrBlink != 0 {
		codes = append(codes, "5")
	}
	if attrs&tcell.AttrReverse != 0 {
		codes = append(codes, "7")
	}
	if attrs&tcell.AttrStrikeThrough != 0 {
		codes = append(codes, "9")
	}
	if uc := style.GetUnderlineColor(); uc.Valid() && uc != tcell.ColorDefault {
		if uc.IsRGB() {
			r, g, b := uc.RGB()
			codes = append(codes, fmt.Sprintf("58;2;%d;%d;%d", r, g, b))
		} else {
			codes = append(codes, fmt.Sprintf("58;5;%d", int(uc&0xff)))
		}
	}
	if len(codes) == 0 {
		return "\x1b[0m"
	}
	return "\x1b[" + strings.Join(codes, ";") + "m"
}

func (p *Pager) screenRowText(row int) string {
	if row < 0 || row >= p.height {
		return ""
	}
	// Find last non-space cell.
	last := -1
	type cellInfo struct {
		r     rune
		comb  []rune
		style tcell.Style
		width int
	}
	cells := make([]cellInfo, p.width)
	for x := 0; x < p.width; x++ {
		r, comb, style, w := p.screen.GetContent(x, row)
		cells[x] = cellInfo{r, comb, style, w}
		if r != ' ' && r != 0 {
			last = x
		}
	}
	if last < 0 {
		return ""
	}
	var b strings.Builder
	var curStyle *tcell.Style
