func (p *Pager) readStreamDoc(d *Document, r io.Reader) {
	if d.streamCh == nil {
		d.streamCh = make(chan streamMsg, 1024)
	}
	ch := d.streamCh
	br := bufio.NewReader(r)
	peek, _ := br.Peek(6)
	compressed := false
	if !opts.SkipExtract && len(peek) >= 4 {
		if _, ok := tryDecompressMagic(peek); ok {
			compressed = true
		}
	}
