		dec := maybeDecompress(data)
		lines, _ := splitLines(dec)
		ch <- streamMsg{batch: lines, raw: dec, eof: true}
		p.postTick()
		return
	}
	for {
		chunk, err := br.ReadBytes('\n')
		if len(chunk) > 0 {
			cp := append([]byte(nil), chunk...)
			ch <- streamMsg{chunk: cp}
			p.postTick()
		}
		if err != nil {
			break
		}
	}
