# Add parseJumpTargetValue & reimplement jumpOffset using it (replace whole jumpOffset func)
start=t.index("func jumpOffset(jt string, bodyRows int, d *Document, targetLine int, p *Pager) int {")
end=t.index("func parseFloat(s string) (float64, error) {", start)
new='''func parseJumpTargetValue(s string, height int, bodyRows int) (int, bool, bool) {
	if s == "section" {
		return 0, true, false
	}
	if height <= 0 {
		height = 24
	}
	var result int
	if strings.HasSuffix(s, "%") {
		v, err := strconv.ParseFloat(strings.TrimSuffix(s, "%"), 64)
		if err != nil {
			return 0, false, false
		}
		result = int(math.Round(float64(height) * v / 100.0))
	} else if strings.HasPrefix(s, ".") || strings.HasPrefix(s, "-.") {
		v, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0, false, false
		}
		result = int(math.Round(float64(height) * v))
	} else if strings.Contains(s, ".") {
		v, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0, false, false
		}
		result = int(math.Round(v))
	} else {
		n, err := strconv.Atoi(s)
		if err != nil {
			return 0, false, false
		}
		if n < 0 {
			result = bodyRows + n
		} else {
			result = n
		}
	}
	if result < 0 || result >= height {
		return result, false, true
	}
	return result, false, false
}

func jumpOffset(jt string, height int, d *Document, targetLine int, p *Pager) int {
	jt = strings.TrimSpace(jt)
	if jt == "" {
		return 0
	}
	if jt == "section" {
		if d == nil || p == nil {
			return 1
		}
		sec := p.sectionStartLineStrict(d, targetLine)
		if sec < 0 {
			if len(p.sectionStarts(d)) == 0 {
				return 1
			}
			return 0
		}
		off := 0
		for _, s := range d.segs {
			if s.LineIdx >= sec && s.LineIdx < targetLine {
				off++
			}
		}
		return off
	}
	// For CLI values the bodyRows used for negative offsets is height-1
	// (when the status line is present).
	res, _, oor := parseJumpTargetValue(jt, height, height-1)
	if oor {
		return 0
	}
	return res
}

