	if envRoot := envConfigRoot(); len(envRoot) > 0 {
		decodeErrs = append(decodeErrs, decodeConfig(envRoot)...)
	}
	if readErr != nil {
		effectiveDebug := debugFlag || cfg.Debug
		if !(isNotFound && !effectiveDebug) {
			fmt.Fprintf(os.Stderr, "failed to read config file: %s\\n", readErr.Error())
		}
	}
	if len(decodeErrs) > 0 {
		fmt.Fprintf(os.Stderr, "decoding failed due to the following error(s):\\n\\n")
		for _, e := range decodeErrs {
