func envConfigRoot() map[string]any {
	root := map[string]any{}
	for _, kv := range os.Environ() {
		i := strings.Index(kv, "=")
		if i < 0 {
			continue
		}
		key, val := kv[:i], kv[i+1:]
		if val == "" {
			continue
		}
		if !strings.HasPrefix(key, "OV_") {
			continue
		}
		path := strings.TrimPrefix(key, "OV_")
		// Viper constructs env names by upper-casing the config key, so only
		// accept keys that are already in that form.
		if path != strings.ToUpper(path) {
			continue
		}
		parts := strings.Split(path, ".")
